window.DIGEST_ARCHIVE=window.DIGEST_ARCHIVE||{};window.DIGEST_ARCHIVE["2026-08-09"]={"date": "2026-08-09", "dateKR": "2026년 8월 9일", "dateEN": "9 August 2026", "total": 88, "sections": [{"code": "TOP", "type": "news", "kTitle": "Section 1. 주요 뉴스", "eTitle": "Section 1. Top News", "items": [{"code": "TOP", "title": "South Korea makes play for large-scale ship recycling", "src": "Splash247", "date": "2026-08-07", "kSum": "한국이 친환경 선박 해체(그린 리사이클링) 시장에서 대형 거점 확보에 나섰다. 엘레강트 엑싯 컴퍼니(Elegant Exit Company)가 국내 해체업체 RM컴퍼니(RM Company) 및 이삭그린텍(ISSAC Green Tech)과 손잡고 아시아 최대 규모가 될 수 있는 해체시설 개발을 추진한다.", "eSum": "South Korea is pushing into large-scale green ship recycling, with Elegant Exit Company teaming up with local recycler RM Company and ISSAC Green Tech to develop what the partners say could become one of Asia's largest recycling facilities.", "kImp": "홍콩협약 발효 이후 친환경 해체 수요가 커지는 가운데, 한국이 남아시아 중심의 해체시장에 새 경쟁축으로 진입하려는 움직임으로 해체 단가와 잔존가치 산정에 영향을 줄 수 있다.", "eImp": "As demand for compliant green recycling grows post-Hong Kong Convention, a Korean hub could introduce a new competitor to the South Asia-dominated market, affecting demolition pricing and residual values.", "url": "https://splash247.com/south-korea-makes-play-for-large-scale-ship-recycling/"}, {"code": "TOP", "title": "Iran weighs ban on US and Israeli ships in Hormuz", "src": "Splash247", "date": "2026-08-07", "kSum": "이란이 호르무즈 해협에서 미국 및 이스라엘 연계 선박의 통항을 금지하는 방안을 검토 중이다. 이란 의회에 상정된 법안 초안은 해당 선박의 통항을 제한하는 내용을 담고 있으며, 이란과 오만은 해협 통항 관리 새 체계 합의에 근접하고 있다.", "eSum": "Iran is considering banning US- and Israeli-linked vessels from transiting the Strait of Hormuz. A draft bill before Iran's parliament would prohibit such vessels, as Tehran and Oman move closer to agreeing a new traffic-management system for the waterway.", "kImp": "전 세계 해상 원유의 약 5분의 1이 지나는 호르무즈에서 선박 국적·연계에 따른 통항 제한이 현실화되면 유조선 운항·보험·용선 전략에 중대한 리스크가 된다.", "eImp": "With roughly a fifth of seaborne oil passing through Hormuz, flag- or ownership-based transit restrictions would pose a major risk to tanker routing, insurance and chartering strategies.", "url": "https://splash247.com/iran-weighs-ban-on-us-and-israeli-ships-in-hormuz/"}, {"code": "TOP", "title": "US sanctions push SeaLead Shipping into liquidation", "src": "Splash247", "date": "2026-08-07", "kSum": "싱가포르 소재 컨테이너 선사 씨리드 시핑(SeaLead Shipping)이 청산 절차에 들어갔다. 지난달 부과된 미국의 전면 제재로 사업이 사실상 마비되면서, 최근 컨테이너 해운업계에서 가장 극적인 성장과 몰락 사례 중 하나로 기록됐다.", "eSum": "Singapore-headquartered container carrier SeaLead Shipping is being liquidated after sweeping US sanctions imposed last month effectively crippled the business, marking one of the most dramatic rises and falls in recent container shipping.", "kImp": "제재가 신흥 컨테이너 선사를 단기간에 청산으로 몰아넣은 사례로, 제재 리스크가 노선·화주·용선 계약 전반에 미치는 파급력을 보여준다.", "eImp": "The case shows how quickly sanctions can drive an emerging carrier into liquidation, underscoring compliance risk across services, shippers and charter contracts.", "url": "https://splash247.com/us-sanctions-push-sealead-shipping-into-liquidation/"}, {"code": "TOP", "title": "Sompo moves to close GPS jamming insurance gap", "src": "Splash247", "date": "2026-08-07", "kSum": "일본 보험사 손보재팬(Sompo Japan)이 GPS 재밍(전파교란)으로 인한 경제적 손실을 겨냥한 해운업계 최초의 보험 상품을 출시했다고 밝혔다. 항법 신호 교란이 빈번해진 분쟁 해역 통항 리스크에 대응하는 조치다.", "eSum": "Japanese insurer Sompo Japan has launched what it claims is the shipping industry's first insurance coverage specifically targeting economic losses from GPS jamming, responding to rising navigation-signal interference in conflict-affected waters.", "kImp": "GPS 재밍이 상선 운항의 상시 위협으로 부상하면서, 관련 손실을 보장하는 신상품은 위험해역 통항 선사의 리스크 관리 수단을 넓힌다.", "eImp": "With GPS jamming now a persistent threat to merchant navigation, dedicated cover expands risk-management options for operators transiting high-risk zones.", "url": "https://splash247.com/sompo-moves-to-close-gps-jamming-insurance-gap/"}, {"code": "TOP", "title": "ADNOC L&S makes $1.3bn VLCC and VLGC swoop", "src": "Splash247", "date": "2026-08-07", "kSum": "아부다비 상장사 애드녹 물류·서비스(ADNOC Logistics & Services)가 13억 달러를 투입해 VLCC 6척을 포함한 11척 매입에 나섰다. UAE의 원유 수출 급증에 대응해 유조선 선대를 확장하려는 조치다.", "eSum": "Abu Dhabi-listed ADNOC Logistics & Services has committed $1.3bn to an 11-ship buying spree, including six VLCCs plus VLGCs, expanding its tanker fleet to capitalise on surging UAE crude exports.", "kImp": "중동 국영 물류사의 대규모 유조선 매입은 VLCC·VLGC 자산가격과 중고선 시장에 상방 압력을 주고, 걸프발 물동량 증가 기대를 반영한다.", "eImp": "A large state-linked tanker acquisition adds upward pressure to VLCC/VLGC asset values and the S&P market, reflecting expectations of rising Gulf export volumes.", "url": "https://splash247.com/adnoc-ls-makes-1-3bn-vlcc-and-vlgc-swoop/"}, {"code": "TOP", "title": "Yangzijiang Maritime takes vessel sales to $500m with bulker quartet", "src": "Splash247", "date": "2026-08-07", "kSum": "양쯔장 마리타임 디벨롭먼트(Yangzijiang Maritime Development)가 신조 벌크선 4척 매각에 합의하며, 지난 9개월간 12척·총 5억 달러 규모의 계약 선박 매각을 달성했다.", "eSum": "Yangzijiang Maritime Development has agreed to sell four newbuild bulkers, taking its contracted vessel sales to $500m across 12 ships in nine months.", "kImp": "선박 투자·매각을 통한 자산 회전 전략이 활발해지고 있음을 보여주며, 벌크선 신조·중고선 거래가 견조하게 유지되고 있음을 시사한다.", "eImp": "The deals highlight an active asset-rotation strategy and signal that bulker newbuild and secondhand transactions remain robust.", "url": "https://splash247.com/yangzijiang-maritime-takes-vessel-sales-to-500m-with-bulker-quartet/"}, {"code": "TOP", "title": "Seaspan becomes first international shipowner to tap panda bond market", "src": "Splash247", "date": "2026-08-07", "kSum": "컨테이너선 임대 대기업 시스팬(Seaspan)이 국제 선주 최초로 중국 위안화 표시 판다본드(panda bond) 시장에서 자금을 조달했다.", "eSum": "Containership lessor Seaspan has become the first international shipowner to tap China's yuan-denominated panda bond market.", "kImp": "선주들의 자금조달 다변화 흐름을 보여주는 상징적 사례로, 위안화 시장이 해운 금융의 새로운 조달 창구로 부상할 가능성을 시사한다.", "eImp": "A landmark in shipowner funding diversification, suggesting the yuan market may emerge as a new channel for maritime finance.", "url": "https://splash247.com/seaspan-becomes-first-international-shipowner-to-tap-panda-bond-market/"}, {"code": "TOP", "title": "China Merchants firms up second DSIC shuttle tanker", "src": "Splash247", "date": "2026-08-07", "kSum": "중국 국영 해운사 차이나머천츠에너지시핑(CMES)이 다롄조선(DSIC)에서 두 번째 셔틀탱커 건조 옵션을 행사했다.", "eSum": "China Merchants Energy Shipping (CMES) has exercised an option for a second shuttle tanker at Dalian Shipbuilding Industry Co (DSIC).", "kImp": "중국 조선·선사의 셔틀탱커 등 고부가 특수선 진출 확대를 보여주며, 특수선 시장에서 중국의 입지 강화를 시사한다.", "eImp": "The order reflects Chinese yards' and owners' push into higher-value specialised tonnage such as shuttle tankers, strengthening China's position in the niche.", "url": "https://splash247.com/china-merchants-firms-up-second-dsic-shuttle-tanker/"}, {"code": "TOP", "title": "Ningbo Ocean Shipping enters car carrier market with Europe service", "src": "Splash247", "date": "2026-08-07", "kSum": "닝보오션시핑(Ningbo Ocean Shipping)이 첫 유럽향 서비스를 개설하며 자동차운반선(PCTC) 시장에 진입했다. 중국산 자동차 수출 급증에 대응한 신규 진입이다.", "eSum": "Ningbo Ocean Shipping has entered the car carrier market, launching its first Europe service on the back of surging Chinese vehicle exports.", "kImp": "중국발 완성차 수출 확대에 힘입어 신규 사업자들이 PCTC 시장에 진입하고 있으며, 자동차운반선 수급과 운임 경쟁 구도에 영향을 준다.", "eImp": "New entrants are joining the PCTC trade on the back of booming Chinese vehicle exports, affecting car-carrier supply-demand and freight competition.", "url": "https://splash247.com/ningbo-ocean-shipping-enters-car-carrier-market-with-europe-service/"}]}, {"code": "ACC", "type": "accident", "kTitle": "Section 2. 해양사고", "eTitle": "Section 2. Accidents", "items": [{"code": "ACC", "title": "MSC boxship sinks deeper off Zhoushan after failed refloating", "src": "Splash247", "date": "2026-08-08", "kSum": "8,401TEU급 컨테이너선 MSC 실바나 8호(MSC Silvana VIII)가 중국 저우산(Zhoushan) 앞바다에서 재부양(refloating)에 실패한 뒤 선체가 더 깊이 침수됐다. 선령 20년·전장 332m 선박으로, 선미가 가라앉고 여러 화물창과 기관실이 침수됐으며 약 3,000톤의 연료유가 제거됐다.", "eSum": "The 8,401 teu containership MSC Silvana VIII has sunk deeper off Zhoushan, China, after refloating attempts failed. The 20-year-old, 332 m ship's stern submerged with several cargo holds and the engine room flooded; around 3,000 tonnes of fuel have been removed.", "kCause": "선박은 6월 22일 광양에서 도착해 저우산 수리구역에 들어간 뒤 어려움에 처했고, 지난달 태풍 바비(Typhoon Bavi)가 저장성을 강타할 때 좌초했다. 좌초의 정확한 원인과 구조적 손상 범위는 아직 불명확하다(추정).", "eCause": "The vessel had entered the Zhoushan repair area on 22 June after arriving from Gwangyang, then ran into difficulty and grounded when Typhoon Bavi struck Zhejiang last month. The precise cause of the grounding and extent of structural damage remain unclear (presumed).", "kLes": "수리·대기 중 선박도 악천후 노출 시 좌초·침수 위험이 크므로 태풍 접근 시 조기 피항 및 계류·감시 강화가 필요하다. 재부양 실패로 연료유 유출 등 환경 리스크가 확대될 수 있어 신속한 연료 제거와 살베지 계획이 중요하다.", "eLes": "Vessels awaiting or under repair remain highly exposed to grounding and flooding in heavy weather; early evacuation, secure mooring and monitoring are needed as typhoons approach. Failed refloating heightens pollution risk, making prompt fuel removal and a robust salvage plan critical.", "url": "https://splash247.com/msc-boxship-sinks-deeper-off-zhoushan-after-failed-refloating/"}, {"code": "ACC", "title": "German bulker Emil hit repeatedly in Russian drone attack off Odesa", "src": "Splash247", "date": "2026-08-07", "kSum": "함부르크 소재 요한 블루멘탈(Johann M. K. Blumenthal) 관리 선박인 라이베리아 선적 17.5만DWT 벌크선 에밀(Emil)이 8월 5일 오데사 남서 약 21해리 해상에서 러시아 드론 다수의 반복 공격을 받았다. 기관 계통이 무력화되고 화재가 발생했으며 조종 불능 상태가 됐고, 선원 퇴선 중에도 추가 공격을 받았다. 우크라이나 밀을 싣던 기니비사우 선적 메라 퀸(Mera Queen)도 피격돼 선원 1명이 사망하고 3명이 부상했다.", "eSum": "The Liberian-flagged, 175,000 dwt bulker Emil, managed by Hamburg's Johann M. K. Blumenthal, was repeatedly struck by Russian drones on 5 August about 21 nm off Odesa, disabling systems, starting a fire and leaving her unable to manoeuvre; another drone struck as the crew abandoned ship. A second vessel, Guinea-Bissau-flagged Mera Queen carrying Ukrainian wheat, was also hit, killing one seafarer and injuring three.", "kCause": "흑해 분쟁 격화 속 러시아군의 상선 대상 드론 공격이 원인이다. 모스크바는 우크라이나 군수물자 운송을 이유로 공격을 인정했으나 검증 가능한 증거는 제시하지 않았다.", "eCause": "The cause was Russian drone strikes on merchant vessels amid the intensifying Black Sea conflict. Moscow acknowledged the attacks, claiming the ships carried military cargo, but offered no verifiable evidence.", "kLes": "흑해는 상선에 가장 위험한 해역이 됐다(최근 5주간 선원 30여 명 사망). 해당 항로 통항 시 위협 정보 공유, 회피 항로, 방호 대책, 선원 대피·구명 절차 강화가 필수다.", "eLes": "The Black Sea has become the most dangerous region for merchant shipping (over 30 seafarers killed in five weeks). Transits require threat-intelligence sharing, rerouting, hardening measures and strengthened evacuation and survival procedures.", "url": "https://splash247.com/german-bulker-hit-repeatedly-in-russian-drone-attack/"}, {"code": "ACC", "title": "Third engineer missing after Minoan Pioneer struck by projectile in Strait of Hormuz", "src": "Marine Insight", "date": "2026-08-05", "kSum": "라이베리아 선적·그리스 운영 벌크선 미노안 파이오니어(Minoan Pioneer)가 8월 3일 22시(UTC) 오만 알카사브 북동 약 20해리 호르무즈 해협에서 미상의 발사체에 피격됐다. 기관실이 타격돼 전면 정전이 발생하고 거주구역에서 화재가 났으며, 선원들이 자체 진화를 시도하던 중 3등기관사 1명이 실종됐다. 나머지 선원은 안전하게 대피했다.", "eSum": "The Liberian-flagged, Greek-operated bulk carrier Minoan Pioneer was struck by an unknown projectile at 2200 UTC on 3 August about 20 nm northeast of Al Khasab, Oman, in the Strait of Hormuz. The engine room was hit, causing a complete blackout and a fire in the accommodation; the third engineer went missing while the crew fought the fire. The remaining crew were safely evacuated.", "kCause": "미상의 발사체가 기관실을 타격한 것이 원인으로, 사고 시점까지 공격 주체를 자처한 세력은 없다. 호르무즈·홍해 일대의 무력 충돌 격화가 배경이다(추정).", "eCause": "The cause was an unknown projectile striking the engine room; no actor claimed responsibility. The backdrop is escalating armed conflict around the Strait of Hormuz and Red Sea (presumed).", "kLes": "고위험 해역 통항 시 기관실·거주구역 등 핵심구역 피격에 대비한 손상통제·소화·정전 대응 훈련과 신속·안전한 퇴선 및 인원 점검 체계가 중요하다. 위협 정보와 통항 시간대 조정이 요구된다.", "eLes": "For high-risk transits, drills for damage control, firefighting and blackout response to strikes on critical spaces, plus rapid safe evacuation and headcount procedures, are vital. Threat intelligence and timing of transits should be managed.", "url": "https://www.marineinsight.com/1-seafarer-goes-missing-after-strike-on-bulker-in-strait-of-hormuz-leads-to-blackout-fire/"}, {"code": "ACC", "title": "ADNOC says three vessels attacked this week transiting Strait of Hormuz", "src": "gCaptain", "date": "2026-08-07", "kSum": "아부다비국영석유회사(ADNOC)는 이번 주 호르무즈 해협 통항 중 자사 선박 3척이 공격받았다고 밝혔다. 분쟁 발발 이후 미사일·드론에 피격된 ADNOC 선박은 총 15척에 이르며, 이로 인해 1명이 사망하고 20명이 부상했다. ADNOC는 이번 3척의 선명이나 손상 정도는 공개하지 않았다.", "eSum": "ADNOC said three of its vessels were attacked this week while transiting the Strait of Hormuz. Since the conflict began, 15 of its ships have been hit by missiles and drones, resulting in one death and 20 injuries. ADNOC did not identify this week's three vessels or detail the damage.", "kCause": "미·이스라엘과 이란 간 분쟁 격화 속 호르무즈 통항 상선을 겨냥한 미사일·드론 공격이 원인이다.", "eCause": "The cause was missile and drone attacks targeting merchant vessels transiting Hormuz amid the escalating US-Israel-Iran conflict.", "kLes": "핵심 에너지 관문에서 상선 피격이 반복되면서 통항량이 정상 대비 급감했다. 선사는 통항 여부 재검토, 호송·보험·위험수당 등 리스크 대응과 대체항로를 종합 검토해야 한다.", "eLes": "Repeated strikes on merchant vessels at a key energy chokepoint have cut transit volumes far below normal. Owners must reassess whether to transit and weigh convoying, insurance, risk pay and alternative routings.", "url": "https://gcaptain.com/adnoc-says-three-vessels-attacked-this-week-as-hormuz-shipping-remains-severely-disrupted/"}, {"code": "ACC", "title": "Indian-flagged MSV Faize Noore Oliya sinks in Red Sea after attack; 14 rescued", "src": "Marine Insight", "date": "2026-08-04", "kSum": "인도 선적 기계식 범선(MSV) 파이제 누레 올리야(Faize Noore Oliya)가 8월 4일 예멘 호데이다 항 남쪽 약 13해리 홍해 해상에서 발사체 공격을 받은 뒤 전복·침몰했다. 예멘 해안경비대가 인도인 13명과 예멘인 1명 등 승선원 14명 전원을 구조해 모카 항으로 이송했으며, 사망자는 없었다.", "eSum": "The Indian-flagged mechanised sailing vessel MSV Faize Noore Oliya overturned and sank in the Red Sea about 13 nm south of Hodeidah, Yemen, on 4 August after a projectile strike. The Yemeni Coast Guard rescued all 14 aboard (13 Indians and one Yemeni), taking them to the Port of Mokha; no casualties were reported.", "kCause": "후티(Houthi) 세력이 통제하는 호데이다 인근 해역에서의 발사체 공격이 침몰의 원인이다. 인도 정부는 무방비 상태의 소형 선박에 대한 도발적 공격이라고 규탄했다.", "eCause": "The cause of the sinking was a projectile strike in waters near Houthi-controlled Hodeidah. India condemned it as an unprovoked attack on a defenceless small vessel.", "kLes": "소형·비무장 상선도 홍해 분쟁 해역에서 공격 표적이 될 수 있으므로 통항 회피 또는 위험 최소화 항로·시간대 선택이 필요하다. 신속한 구조 공조가 인명 피해를 막은 사례로, 조난 통신·구명 준비가 중요하다.", "eLes": "Even small, unarmed vessels can be targeted in the Red Sea conflict zone, so avoidance or lower-risk routing and timing are needed. Rapid coordinated rescue prevented loss of life, underscoring the value of distress communications and survival readiness.", "url": "https://www.marineinsight.com/indian-flagged-ship-with-14-crew-members-overturns-sinks-in-red-sea-after-attack/"}]}, {"code": "PSC", "type": "news", "kTitle": "Section 3. 항만국통제", "eTitle": "Section 3. Port State Control", "items": [{"code": "PSC", "title": "RiSK4SEA PSI Outlook August 2026: Diverging PSC enforcement recovery leaves bulkers under continued pressure", "src": "Safety4Sea", "date": "2026-08-05", "kSum": "리스크포씨(RiSK4SEA)의 2026년 8월 PSC 스트레스 지수(PSI) 전망에 따르면 6월 4개 주요 선종이 모두 '위기 구간'(PSI-9)에 진입한 이후 글로벌 항만국통제(PSC) 집행 환경이 크게 완화됐다. 탱커·컨테이너·일반화물선은 PSI-2 '개선 추세'로 회복했으나, 벌크선만 PSI-6 '성능 악화'로 여전히 압박을 받고 있다. 벌크선은 선체·설비 결함과 안전관리체계(SMS) 관련 지적 증가로 KPI 스트레스가 +10.4%에 달한다.", "eSum": "RiSK4SEA's August 2026 PSC Stress Index (PSI) Outlook shows the global PSC enforcement climate easing markedly after all four major segments hit the PSI-9 'Critical Risk Zone' in June. Tankers, containers and general cargo have reverted to PSI-2 'Improving Trend', while bulkers alone remain under pressure at PSI-6 'Performance Deteriorating', with KPI stress at +10.4% driven by ship structure/equipment and SMS deficiencies.", "kImp": "벌크선 운항 성능 악화가 지속돼 향후 억류 압력으로 재확산될 수 있어 선제적 관리가 요구된다.", "eImp": "Persistent bulker performance deterioration could translate into renewed detention pressure, warranting proactive management.", "url": "https://safety4sea.com/cm-risk4sea-psi-outlook-august-2026/"}, {"code": "PSC", "title": "IMO expands global PSC data exchange with Black Sea, Caribbean MoUs", "src": "Safety4Sea", "date": "2026-08-05", "kSum": "국제해사기구(IMO)가 흑해 양해각서(Black Sea MoU)와 카리브해 양해각서(Caribbean MoU)를 글로벌 통합 선박정보시스템 기반 PSC 데이터 교환 체계에 편입하며 항만국통제 데이터 공유를 확대했다. 아르세니오 도밍게스(Arsenio Dominguez) IMO 사무총장이 참석한 서명식을 통해 지역 MoU 간 검사 이력 공유가 강화된다.", "eSum": "The IMO has expanded its global PSC data exchange by bringing the Black Sea MoU and Caribbean MoU into the shared framework, following a signing ceremony attended by Secretary-General Arsenio Dominguez. The move strengthens cross-regional sharing of inspection histories among port state control regimes.", "kImp": "지역 MoU 간 검사 데이터 통합은 표적 선박 선별 정확도를 높여 저성능 선박의 회피 여지를 줄인다.", "eImp": "Integrating inspection data across regional MoUs sharpens targeting and reduces room for substandard ships to evade scrutiny.", "url": "https://safety4sea.com/imo-expands-global-psc-data-exchange-with-black-sea-caribbean-mous/"}, {"code": "PSC", "title": "Complying with CIC 2026 on Cargo Securing: A best practice guide", "src": "Safety4Sea", "date": "2026-08-03", "kSum": "도쿄·파리 MoU가 9월 1일~11월 30일 실시하는 화물 고박(cargo securing) 집중점검(CIC)에 대비한 모범사례 가이드가 공개됐다. 검사관(PSCO)은 10개 질문 설문으로 SOLAS 화물 고박 요건 준수 여부를 점검하며, 이 중 7개 항목은 억류 사유가 될 수 있다.", "eSum": "A best-practice guide has been published to help ships prepare for the Tokyo and Paris MoU Concentrated Inspection Campaign (CIC) on cargo securing, running 1 September to 30 November. PSCOs will apply a 10-question checklist on SOLAS cargo securing compliance, seven items of which can be grounds for detention.", "kImp": "화물 고박 CIC 기간 결함은 억류로 이어질 수 있어 선사의 사전 점검·문서화가 중요하다.", "eImp": "Deficiencies during the cargo-securing CIC can lead to detention, making pre-campaign checks and documentation critical.", "url": "https://safety4sea.com/cm-complying-with-cic-2026-on-cargo-securing-a-best-practice-guide/"}]}, {"code": "PCTC", "type": "news", "kTitle": "Section 4. 자동차운반선", "eTitle": "Section 4. PCTC / Car Carriers", "items": [{"code": "PCTC", "title": "Ningbo Ocean Shipping dips its toes into car-carrying waters", "src": "The Loadstar", "date": "2026-08-07", "kSum": "닝보 오션 시핑(Ningbo Ocean Shipping, NBOSCO)이 유럽 선주 아틀라스 EMF(Atlas EMF)로부터 7,000 CEU급 LNG 이중연료선 '클린 스타(Clean Star)'를 하루 8만 달러, 2년 계약으로 용선하며 차량 운송에 진출했다. 이 선박은 5,400대의 신에너지차를 싣고 수에즈 운하를 경유해 이탈리아 제노바·조이아타우로와 스페인 바르셀로나로 향한다. MSC, CMA CGM(세바 로지스틱스), HMM에 이어 정기선사가 자동차운반선으로 영역을 넓힌 최신 사례다.", "eSum": "Ningbo Ocean Shipping (NBOSCO), the liner unit of Ningbo-Zhoushan Port Group, has moved into vehicle transport by chartering the 7,000 ceu Clean Star from Atlas EMF at $80,000/day for two years. The ship left Ningbo with 5,400 NEVs bound for Genoa, Gioia Tauro and Barcelona, routing via Suez. It is the latest liner operator to enter car carriers after MSC, CMA CGM (via Ceva) and HMM.", "kImp": "컨테이너 선사들의 자동차운반선 진출이 구조적 흐름으로 굳어지고 있음을 보여준다.", "eImp": "It underlines how container carriers moving into car-carrying is becoming a structural feature of the trade.", "url": "https://theloadstar.com/ningbo-ocean-shipping-dips-its-toes-into-car-carrying-waters/"}, {"code": "PCTC", "title": "Greater Bay Area beefs up auto logistics", "src": "Seatrade Maritime", "date": "2026-08-07", "kSum": "광저우 항만그룹(Guangzhou Port Group)과 광저우 대중교통그룹이 공동 개발한 '광둥-홍콩-마카오 대만구 차량수출 준비센터'가 광저우항 난사(Nansha) 터미널에서 본격 가동에 들어갔다. 약 3,300㎡ 규모로 월 3,000대 처리 능력을 갖춘 이 시설은 차량 정비부터 항만 물류까지 원스톱 수출 서비스를 제공한다. 난사 자동차항은 8개 전용 선석에 연 300만 대 이상의 처리 능력을 갖춘 중국 남부 최대 로로 허브다.", "eSum": "A new Greater Bay Area Vehicle Export Preparation Center, jointly developed by Guangzhou Port Group and Guangzhou Public Transport Group, has begun full operation at Guangzhou port's Nansha terminal. The roughly 3,300 sqm facility offers end-to-end pre-shipment services with a monthly capacity of nearly 3,000 units. Nansha, South China's largest ro-ro vehicle hub, handled 268,000 foreign-trade vehicles in H1 2026 across eight specialised berths.", "kImp": "중국의 자동차 수출 급증에 대응한 로로 항만·물류 인프라 확충 흐름을 보여준다.", "eImp": "It reflects China's push to expand ro-ro port and logistics infrastructure to keep pace with booming vehicle exports.", "url": "https://www.seatrade-maritime.com/ports-logistics/greater-bay-area-beefs-up-auto-logistics"}]}, {"code": "WW", "type": "news", "kTitle": "Section 5. 발레니우스 빌헬름센", "eTitle": "Section 5. Wallenius Wilhelmsen", "items": [{"code": "WW", "title": "최근 7일간 신규 소식이 확인되지 않았습니다", "src": "—", "date": "2026-08-09", "kSum": "이 기간 해당 분야의 신선한 기사가 확인되지 않았습니다. 다음 갱신 시 보완됩니다.", "eSum": "No fresh items were confirmed in this category over the last 7 days; it will be updated in the next cycle.", "kImp": "-", "eImp": "-", "url": "https://brightatsea-alt.github.io/maritime-daily-digest/"}]}, {"code": "EE", "type": "news", "kTitle": "Section 6. 에너지 효율·탈탄소", "eTitle": "Section 6. Energy Efficiency", "items": [{"code": "EE", "title": "Opportunity Green warns against weakening IMO Net-Zero Framework", "src": "Safety4Sea", "date": "2026-08-05", "kSum": "기후 NGO 오퍼튜니티 그린(Opportunity Green)은 IMO 회원국들에게 넷제로 프레임워크(Net-Zero Framework, NZF)를 지지하고 합의된 구조를 약화시킬 수 있는 제안을 거부할 것을 촉구했다. 각국 정부가 IMO 협상을 재개하는 시점에 나온 성명이다.", "eSum": "Climate NGO Opportunity Green urged IMO member states to support the Net-Zero Framework (NZF) and reject proposals that could weaken its agreed structure. The appeal comes as governments prepare to resume negotiations at the IMO.", "kImp": "IMO 넷제로 프레임워크의 강도는 향후 국제 해운의 연료 전환과 탈탄소 투자 방향을 좌우한다.", "eImp": "The strength of the IMO Net-Zero Framework will shape the direction of fuel transition and decarbonization investment across global shipping.", "url": "https://safety4sea.com/opportunity-green-warns-against-weakening-imo-net-zero-framework/"}, {"code": "EE", "title": "IMarEST analysis finds levy-based framework best positioned to meet IMO targets", "src": "Safety4Sea", "date": "2026-08-06", "kSum": "해양공학·과학·기술협회(IMarEST)는 부과금(levy) 기반 프레임워크가 IMO의 온실가스 감축 목표 달성에 가장 유리하다는 분석을 내놓으며 회원국들에게 이를 고려할 것을 요청했다. 넷제로 프레임워크(NZF) 협상이 계속되는 가운데 나온 분석이다.", "eSum": "The Institute of Marine Engineering, Science and Technology (IMarEST) called on IMO member states to consider its analysis finding that a levy-based framework is best positioned to meet the organization's GHG targets. The analysis comes as Net-Zero Framework negotiations continue.", "kImp": "탄소 부과금 구조 채택 여부는 해운의 대체연료 경제성과 감축 목표 달성 가능성에 결정적 영향을 미친다.", "eImp": "Whether a carbon levy structure is adopted will critically affect the economics of alternative fuels and the feasibility of meeting shipping's reduction targets.", "url": "https://safety4sea.com/imarest-analysis-finds-levy-based-framework-best-positioned-to-meet-imo-targets/"}, {"code": "EE", "title": "Pacific nations issue proposal to address IMO Net-Zero Framework concerns", "src": "Safety4Sea", "date": "2026-08-06", "kSum": "피지, 키리바시, 나우루, 팔라우, 투발루, 바누아투 등 태평양 도서국들이 IMO 넷제로 프레임워크(NZF)의 남은 우려를 해소하기 위한 MARPOL 부속서 VI 개정안을 제출했다. 이들은 선박 온실가스 감축을 위한 중기 조치 채택을 지지한다.", "eSum": "Pacific nations - Fiji, Kiribati, Nauru, Palau, Tuvalu and Vanuatu - submitted proposals for amendments to MARPOL Annex VI to address outstanding concerns over the IMO Net-Zero Framework. They aim to support the adoption of mid-term GHG reduction measures for ships.", "kImp": "기후 취약 도서국의 제안은 NZF 채택 협상의 정치적 균형과 감축 야심 수준에 영향을 준다.", "eImp": "Proposals from climate-vulnerable island states influence the political balance and ambition level of the NZF adoption negotiations.", "url": "https://safety4sea.com/pacific-nations-issue-proposal-to-address-imo-net-zero-framework-concerns/"}, {"code": "EE", "title": "NYK joint venture launches new LNG carrier for China's Cnooc Group", "src": "Safety4Sea", "date": "2026-08-06", "kSum": "NYK 라인(NYK Line)이 참여한 합작사가 중국 씨눅(Cnooc) 그룹을 위한 신규 LNG 운반선을 진수했다. 이 선박은 장기 용선 계약에 따라 액화천연가스 수송을 시작할 예정이다.", "eSum": "A joint venture involving NYK Line launched a new LNG carrier for China's Cnooc Group. The vessel is set to begin transporting liquefied natural gas under a long-term charter contract.", "kImp": "LNG는 해운 탈탄소의 과도기 연료로 논쟁이 있으나, 신규 LNG 운반선 확대는 중국 가스 수입 인프라와 연계된 연료 전환 흐름을 보여준다.", "eImp": "Though LNG's role as a transition fuel is debated, expanding the LNG carrier fleet reflects fuel-transition momentum tied to China's gas import infrastructure.", "url": "https://safety4sea.com/nyk-joint-venture-launches-new-lng-carrier-for-chinas-cnooc-group/"}, {"code": "EE", "title": "SMM 2026 Launches Energy Efficiency Hub", "src": "MarineLink", "date": "2026-08-06", "kSum": "세계 최대 해양산업 전시회 SMM이 9월 1~4일 에너지효율에 특화된 전용 전시관 '에너지 효율 허브(Energy Efficiency Hub)'를 신설한다. 유럽·아시아·중동 24개 기업이 풍력보조추진, 태양광, 선상 탄소포집(OCCS), 대체연료, 폐열회수 등 즉시 배출 저감이 가능한 기술을 선보인다.", "eSum": "SMM, the world's leading maritime industry event, will launch an Energy Efficiency Hub - a dedicated exhibition area for energy efficiency - on September 1-4, 2026. Twenty-four companies from Europe, Asia and the Middle East will showcase wind-assisted propulsion, solar, onboard carbon capture (OCCS), alternative-fuel and waste-heat-recovery technologies that deliver immediate emissions cuts.", "kImp": "어떤 저탄소 연료가 우세할지 불확실한 가운데, 즉시 적용 가능한 에너지효율 기술이 해운 전환의 핵심 동력으로 부상하고 있다.", "eImp": "With no clear winner among low-carbon fuels, immediately deployable energy-efficiency technologies are emerging as a key driver of the shipping transition.", "url": "https://www.marinelink.com/news/smm-launches-energy-efficiency-hub-541860"}, {"code": "EE", "title": "441 m sailing boxship concept dwarfs Emma Maersk", "src": "Splash247", "date": "2026-08-07", "kSum": "거대 고체 돛과 태양광, 배터리, 수소·전기 추진을 결합한 441.5m 초대형 컨테이너선(ULCS) 콘셉트가 공개되며 풍력보조 해운의 확장 한계를 둘러싼 논쟁을 촉발했다. 선박건축가 헤르베르트 블뤼멜(Herbert Blumel)의 설계로, 하팍로이드(Hapag-Lloyd)·CMA CGM도 대형 풍력보조 컨테이너선을 검토 중이다.", "eSum": "A radical 441.5 m ultra-large containership (ULCS) concept combining giant solid sails, solar power, batteries and hydrogen or electric propulsion has sparked debate over how far wind-assisted shipping can be scaled. Designed by naval architect Herbert Blumel, it comes as Hapag-Lloyd and CMA CGM also study large wind-assisted containership designs.", "kImp": "컨테이너선은 갑판 공간·크레인 접근성 제약으로 풍력 도입이 가장 어려운 선종으로, 대형 풍력선 논의는 해운 탈탄소의 기술적 한계를 시험한다.", "eImp": "Containerships are the hardest segment for wind due to deck-space and crane-access constraints, so large sailing-ship concepts test the technical limits of shipping decarbonization.", "url": "https://splash247.com/441-m-sailing-boxship-concept-dwarfs-emma-maersk/"}, {"code": "EE", "title": "First multipurpose cargo vessel installs wind-assisted propulsion", "src": "The Maritime Executive", "date": "2026-08-07", "kSum": "스페인 풍력추진 기업 바운드4블루(bound4blue)가 신조 다목적선 '나 히로 에 파에(Na Hiro E Pae)'에 22m 높이 eSail 흡입식 돛을 설치해, 세계 최초로 다목적 화물선에 풍력추진을 적용했다. 이 시스템은 에너지 소비를 약 10% 줄일 것으로 기대되며, 이 선박은 바이오·e연료 사용도 가능하다.", "eSum": "Spanish wind-propulsion company bound4blue installed a 22-meter eSail suction sail on the newbuild multipurpose vessel Na Hiro E Pae, the first known multipurpose cargo ship to adopt wind propulsion. The system is expected to cut energy consumption by about 10%, and the vessel can also run on biofuel or e-fuel.", "kImp": "운항 유연성 탓에 풍력 도입이 어려웠던 다목적선까지 흡입식 돛이 확산되며 풍력보조추진의 적용 선종이 넓어지고 있다.", "eImp": "Extending suction sails to multipurpose vessels - long considered difficult due to operational flexibility - broadens the range of ship types adopting wind-assisted propulsion.", "url": "https://maritime-executive.com/article/first-multipurpose-cargo-vessel-installs-wind-assisted-propulsion"}, {"code": "EE", "title": "Negative impact of EU ETS seen on port connectivity", "src": "Seatrade Maritime", "date": "2026-08-06", "kSum": "스페인 항만공사(Puertos del Estado) 모니터링 그룹은 EU 배출권거래제(EU ETS)의 직접적 영향으로 북유럽 항만 연결성이 5%, 지중해 항만은 18% 감소했다고 밝혔다. 정기선사들이 이집트·영국 등 EU 밖 항만으로 기항을 재편했으며, 알파라이너(Alphaliner)는 기항 변경의 약 76%가 EU ETS 때문이라고 추정했다.", "eSum": "A monitoring group of Spain's port authority Puertos del Estado found EU ETS directly cut port connectivity 5% at North European ports and 18% at Mediterranean ports. Liner operators have rerouted calls to non-EU hubs in Egypt and the UK, with Alphaliner estimating about 76% of the call changes were due to the EU ETS.", "kImp": "탄소가격 규제가 항로·기항 재편이라는 '탄소누출(carbon leakage)' 부작용을 낳으면서, IMO 글로벌 체계와의 정합성 확보 필요성이 부각된다.", "eImp": "Carbon-pricing rules are producing 'carbon leakage' via rerouting, underscoring the need to align regional measures with a global IMO framework.", "url": "https://www.seatrade-maritime.com/regulations/negative-impact-of-eu-ets-seen-on-port-connectivity"}]}, {"code": "DIG", "type": "news", "kTitle": "Section 7. 디지털라이제이션", "eTitle": "Section 7. Digitalization", "items": [{"code": "DIG", "title": "BIMCO warns against overreliance on AI contract drafting", "src": "Splash247", "date": "2026-08-07", "kSum": "빔코(BIMCO)는 AI가 해운 계약 업무에 빠르게 확산되고 있으나 조항 작성·검토 시 인간의 판단이 여전히 필수적이라고 경고했다. 문서위원회 위원 설문에서 20%가 이미 AI 도구를 사용 중이고 70%가 3~5년 내 도입을 예상했다. 빔코는 AI 생성 조항이 위험 배분을 왜곡하거나 법적·보험적 함의를 놓칠 수 있다고 지적하며 계약 진위 확인 도구(SmartCon)를 도입했다.", "eSum": "BIMCO warned that while AI is rapidly entering shipping's contractual work, human judgement remains essential when drafting and reviewing clauses. A survey found 20% of Documentary Committee members already use AI tools and 70% expect adoption within five years. BIMCO cautioned that AI-generated clauses could misallocate risk or overlook legal and insurance implications, and introduced a free SmartCon tool to verify contract authenticity.", "kImp": "표준계약을 관장하는 빔코(BIMCO)의 경고는 AI 확산 속에서 계약 표준화·진위성 관리가 새로운 리스크 이슈로 부상하고 있음을 시사한다.", "eImp": "The warning from the body behind industry-standard contracts highlights authenticity and risk-allocation as emerging concerns as AI drafting spreads.", "url": "https://splash247.com/bimco-warns-against-overreliance-on-ai-contract-drafting/"}, {"code": "DIG", "title": "Shipping's AI forecasters run into the limits of history", "src": "Splash247", "date": "2026-08-06", "kSum": "머신러닝이 운임 예측을 개선하고 있으나 해운 특유의 변동성은 여전히 어떤 모델로도 다루기 어렵다는 분석이 나왔다. 2012~2024년 28개 연구 검토 결과 지정학적 충격·규제·급작스러운 공급 교란은 과거 데이터로 신뢰성 있게 포착되지 않았다. 전문가들은 AI가 분석을 예리하게 하지만 해운 사이클을 없애거나 인간의 판단을 대체하지는 못한다고 결론지었다.", "eSum": "Machine learning is improving freight-rate forecasting, but shipping's volatility remains beyond the reach of any model, according to a review of 28 studies from 2012-2024. Geopolitical shocks, regulation and sudden supply disruptions cannot be reliably captured from historical data. Experts agree AI sharpens analysis but will not remove shipping cycles or replace human judgement.", "kImp": "해운사들의 AI 예측 도입이 빨라지는 가운데 그 한계를 명확히 짚어 과도한 의존을 경계하게 한다.", "eImp": "As shipping accelerates AI adoption for forecasting, the piece clarifies its limits and cautions against overreliance.", "url": "https://splash247.com/shippings-ai-forecasters-run-into-the-limits-of-history/"}, {"code": "DIG", "title": "Singapore's 5G maritime network opens the door to AI, remote pilotage and autonomous operations", "src": "The Digital Ship", "date": "2026-08-03", "kSum": "싱가포르(Singapore)의 해상 5G 네트워크 투자가 원격 진료(telemedicine), 자율운항, 원격 도선에 필요한 연결성을 선주에게 제공하고 있다. 고대역·저지연 연결은 AI 기반 운영과 원격 조종을 뒷받침한다. 항만 인근 해역에서 스마트 해운 서비스의 상용화 기반이 마련되고 있다.", "eSum": "Singapore's investment in a maritime 5G network is giving shipowners the connectivity needed for telemedicine, autonomous vessels and remote pilotage. The high-bandwidth, low-latency coverage underpins AI-driven operations and remote control in port waters. It lays the groundwork for commercial smart-shipping services.", "kImp": "항만 인근 고성능 통신망 구축은 자율운항·원격 도선 상용화의 기반 인프라로서 스마트 해운 전환을 가속한다.", "eImp": "High-performance coastal connectivity provides foundational infrastructure to accelerate autonomous and remotely piloted operations.", "url": "https://thedigitalship.com/news/maritime-satellite-communications/singapores-5g-maritime-network-opens-the-door-to-ai-remote-pilotage-and-autonomous-operations/"}, {"code": "DIG", "title": "PIL expands process intelligence push with Celonis and WNS", "src": "Splash247", "date": "2026-08-06", "kSum": "퍼시픽 인터내셔널 라인스(PIL)가 셀로니스(Celonis), WNS와 손잡고 글로벌 프로세스 인텔리전스 센터를 확장하며 90개국 사업의 디지털 전환을 가속한다. 100척 이상을 운영하는 PIL은 셀로니스 플랫폼으로 업무 프로세스의 실시간 디지털 모델을 구축해 병목을 식별하고 자동화·AI 기반을 마련한다.", "eSum": "Pacific International Lines has partnered Celonis and WNS to expand its global Process Intelligence Centre of Excellence, accelerating digital transformation across operations in 90 countries. The carrier, operating more than 100 containerships, uses the Celonis platform to build a real-time digital model of its business processes to spot bottlenecks and lay a foundation for AI-driven automation.", "kImp": "컨테이너 선사가 프로세스 마이닝·AI를 백오피스까지 확대하며 운영 효율화의 디지털 기반을 넓히고 있음을 보여준다.", "eImp": "It shows a container carrier extending process mining and AI into back-office operations to build a base for automation.", "url": "https://splash247.com/pil-expands-process-intelligence-push-with-celonis-and-wns/"}]}, {"code": "TECH", "type": "news", "kTitle": "Section 8. 선박관리 기술", "eTitle": "Section 8. Ship Manager Technical", "items": [{"code": "TECH", "title": "bound4blue Installs eSAILs on South Pacific Multipurpose Vessel", "src": "MarineLink", "date": "2026-08-04", "kSum": "풍력 보조 추진 전문기업 바운드포블루(bound4blue)가 프랑스령 폴리네시아 선사 SNA Tuha'a Pae의 신조 다목적선 나 히로 에 파에(Na Hiro E Pae)에 22m 높이의 흡입식 돛(eSAIL) 설치를 완료했다. 다목적 화물선으로는 세계 최초의 풍력 추진 시스템 채택 사례로 평가된다. 회사는 이번 설치가 소형·다목적선까지 풍력 추진이 확산되는 이정표라고 밝혔다.", "eSum": "Wind-assist specialist bound4blue completed installation of a 22-metre-high eSAIL suction sail on the newbuild multipurpose vessel Na Hiro E Pae, owned by French Polynesia's SNA Tuha'a Pae Shipping Company. It is described as the first multipurpose cargo vessel worldwide to adopt a wind propulsion system, marking a milestone for wider adoption of the technology.", "kImp": "흡입식 돛 등 풍력 보조 추진 장치(WAPS/ESD)가 소형·다목적선까지 확산되고 있어, 기술팀은 에너지효율 개선과 EEXI/CII 대응을 위한 ESD 적용 대상과 도입 시점을 재검토할 필요가 있다.", "eImp": "With wind-assist devices spreading even to small multipurpose vessels, technical teams should reassess which ships and timing make sense for ESD retrofits to improve energy efficiency and EEXI/CII compliance.", "url": "https://www.marinelink.com/news/boundblue-installs-esails-south-pacific-541757"}, {"code": "TECH", "title": "Carnival Cruise Line Implement Jotun Hull Cleaning Solution", "src": "MarineLink", "date": "2026-08-04", "kSum": "카니발 크루즈 라인(Carnival Cruise Line)이 요툰(Jotun)과 협약을 맺고 로봇형 선체 청소 기술인 헐 스케이팅 솔루션(Hull Skating Solution, HSS)을 크루즈 업계 최초로 도입한다. 카니발 프라이드(Carnival Pride)호에 적용되며, 상시 청결 선체 유지를 통해 연료 소비와 탄소 배출을 줄이는 것이 목표다. 협약에는 호환 방오도료, 지속 모니터링, 선체 검사, DNV가 검증한 '상시 청결 선체' 보증이 포함된다.", "eSum": "Carnival Cruise Line signed an agreement with Jotun to deploy its robotic Hull Skating Solution (HSS) on Carnival Pride, becoming the first cruise operator to adopt the proactive hull-cleaning technology. The deal bundles compatible hull coating, continuous monitoring, hull inspections and an 'always clean hull' guarantee independently verified by DNV.", "kImp": "선체 오손 관리를 도킹 주기 중심에서 상시 프로액티브 방식으로 전환하는 사례로, 기술팀의 선체 성능·연료효율 관리와 방오 전략 수립에 직접적인 참고가 된다.", "eImp": "A shift from docking-cycle cleaning to continuous proactive hull management, directly relevant to technical teams' hull-performance, fuel-efficiency and antifouling strategy decisions.", "url": "https://www.marinelink.com/news/carnival-cruise-line-implement-jotun-hull-541763"}, {"code": "TECH", "title": "Tymor Marine Conducts Digital Survey Aboard Global Mercy", "src": "MarineLink", "date": "2026-08-05", "kSum": "스코틀랜드 해양기술 기업 타이모 마린(Tymor Marine)이 세계 최대 민간 병원선 글로벌 머시(Global Mercy)호에서 자체 디지털 기술을 이용해 경하중량 조사(lightweight survey)와 경사시험(inclining test)을 완료했다. 작업은 라스팔마스 항에서의 연례 정비 기간에 수행됐으며, 영상 기반 흘수 판독 기술(DRFT MRKS)과 데드웨이트 갱신 기술(DeadW8)이 사용됐다.", "eSum": "Scottish maritime technology firm Tymor Marine completed a lightweight survey and inclining test aboard the world's largest civilian hospital ship, Global Mercy, using its own digital survey technologies during the vessel's annual maintenance period in Las Palmas. Tools deployed included video-based draft reading (DRFT MRKS) and deadweight updating (DeadW8).", "kImp": "경사시험과 복원성 정보는 선박의 적재·운항 한계를 결정하므로, 디지털 조사 기술은 기술팀의 정비 기간 검사 효율과 복원성 관리 정확도를 높이는 수단이 된다.", "eImp": "Because inclining tests and stability data define a vessel's loading and operating limits, digital survey technology can improve technical teams' inspection efficiency and stability-management accuracy during maintenance windows.", "url": "https://www.marinelink.com/news/tymor-marine-conducts-digital-survey-541814"}]}, {"code": "HR", "type": "news", "kTitle": "Section 9. 해기인력·선원", "eTitle": "Section 9. Marine HR", "items": [{"code": "HR", "title": "Seafarer Happiness Slips as Chronic Strain Replaces Crisis, Survey Finds", "src": "gCaptain", "date": "2026-08-03", "kSum": "gCaptain은 선원행복지수(SHI) 2026년 2분기 하락을 보도하며 인구통계별 격차를 부각했다. 여성 선원의 평균 행복도는 6.06점으로 남성 7.13점보다 크게 낮았고, 중동 해역 근무자는 4.94점, 컨테이너선 선원은 5.85점으로 업계 평균을 밑돌았으며 35~55세 중견 선원의 사기가 가장 낮았다. 젊은 세대는 '육상 직업 대비 이점이 없다'고 답해 채용·유지 우려가 커졌다.", "eSum": "gCaptain reported the Q2 2026 SHI decline with a focus on demographic gaps: female respondents averaged 6.06 versus 7.13 for men, Middle East crews scored lowest at 4.94, container crews 5.85, and mid-career seafarers (35-55) reported the lowest morale. Younger workers said there are 'no advantages remaining compared with a shore job,' signaling recruitment and retention risks.", "kImp": "여성·중견·컨테이너선 등 특정 집단의 사기 저하는 다양성(diversity)과 인력 유지 전략의 취약점을 드러내며, 우수 고용주의 특징(교대 일정 준수, 적기 교대, 성과 기반 승진)이 유지 해법으로 제시된다.", "eImp": "Sharp morale gaps for women, mid-career and container crews expose weaknesses in diversity and retention strategy, while high-performing employers (honoring crew-change schedules, timely reliefs, merit-based promotion) point to solutions.", "url": "https://gcaptain.com/seafarer-happiness-slips-as-chronic-strain-replaces-crisis-survey-finds/"}]}, {"code": "HSEQ", "type": "news", "kTitle": "Section 10. HSEQ·손해방지", "eTitle": "Section 10. HSEQ", "items": [{"code": "HSEQ", "title": "UK Chamber of Shipping maps safety challenges as industry transitions toward net zero", "src": "SAFETY4SEA", "date": "2026-08-03", "kSum": "영국선주협회(UK Chamber of Shipping)가 신보고서 'Alternative Fuels: Building the Safety Evidence Base'를 통해 넷제로 전환 과정에서 대두되는 안전 과제를 정리했다. 암모니아·메탄올·수소 등 대체연료 도입에 필요한 안전 근거(evidence base) 구축, 선원 교육, 위험성 평가 체계 강화의 필요성을 강조했다.", "eSum": "The UK Chamber of Shipping's new report 'Alternative Fuels: Building the Safety Evidence Base' maps the safety challenges arising as the industry transitions toward net zero, calling for a stronger safety evidence base, seafarer training and risk-assessment frameworks for alternative fuels such as ammonia, methanol and hydrogen.", "kImp": "대체연료 선대 도입을 준비하는 선박관리사 HSEQ팀은 연료별 위험요소와 교육·절차 공백을 사전에 식별해 SMS에 반영해야 한다.", "eImp": "Ship managers' HSEQ teams preparing for alternative-fuel tonnage should identify fuel-specific hazards and training/procedure gaps early and embed them into the SMS.", "url": "https://safety4sea.com/uk-chamber-of-shipping-maps-safety-challenges-as-industry-transitions-toward-net-zero/"}, {"code": "HSEQ", "title": "West P&I Club acquires 100% of Nordic", "src": "SAFETY4SEA", "date": "2026-08-03", "kSum": "웨스트 P&I 클럽(West P&I Club)이 고정보험료(fixed premium) 전문 보험사 노르딕(Nordic Marine Insurance)의 지분 100%를 인수했다고 발표했다. 노르딕은 웨스트의 선체보험(H&M) 북을 계속 운영하며, 웨스트는 스칸디나비아 지역 P&I 입지 확대와 지연보험(Delay Insurance) 수요 대응을 강화한다.", "eSum": "West P&I Club announced the full (100%) acquisition of fixed-premium insurer Nordic Marine Insurance. Nordic will continue to manage West's Hull & Machinery book, helping West expand its P&I presence in Scandinavia and meet growing demand for specialist Delay Insurance.", "kImp": "회원사 관점에서 보험·손실예방 서비스 창구가 넓어지는 것을 의미하며, HSEQ/보험 담당은 클럽 재편에 따른 커버리지·손실예방 지원 변화를 점검할 필요가 있다.", "eImp": "For members, this broadens the club's insurance and loss-prevention offering; HSEQ/insurance managers should monitor how coverage and loss-prevention support evolve after the consolidation.", "url": "https://safety4sea.com/west-pi-club-acquires-100-of-nordic/"}, {"code": "HSEQ", "title": "Lessons learned: Line handling operations are common but inherently hazardous", "src": "SAFETY4SEA", "date": "2026-08-05", "kSum": "영국항해학회(Nautical Institute)가 조선소 접안 작업 중 계류줄(mooring line)이 장력을 받으면서 예인선 갑판원이 사망한 사고의 교훈을 공유했다. 계류·라인핸들링은 일상적이지만 본질적으로 위험한 작업으로, 스냅백(snap-back) 구역 관리와 작업별 위험성 평가가 핵심이라고 강조했다.", "eSum": "The Nautical Institute shared lessons from an incident in which a tug deckhand was fatally injured when a mooring line came under tension during shipyard berthing. It stresses that line-handling, though routine, is inherently hazardous and requires strict snap-back zone management and task-specific risk assessment.", "kImp": "계류·라인핸들링 작업의 스냅백 위험, 지휘·통신, 위치선정을 툴박스미팅과 위험성평가에 반영해 재발을 방지해야 한다.", "eImp": "HSEQ teams should reinforce snap-back awareness, positioning and communication in toolbox talks and risk assessments for all mooring/line-handling operations.", "url": "https://safety4sea.com/lessons-learned-line-handling-operations-are-common-but-inherently-hazardous/"}, {"code": "HSEQ", "title": "Key measures to prevent rescue boat launching accidents at sea", "src": "SAFETY4SEA", "date": "2026-08-03", "kSum": "구조정(rescue boat) 진수 훈련은 비상대응에 필수적이지만 해상에서 가장 위험한 일상 작업 중 하나로, 점검과 안전절차 준수가 관건이라고 SAFETY4SEA가 정리했다. 훅·데빗·폴(hook, davit, fall) 등 진수장비 점검과 낙하·이탈 방지 조치의 중요성을 강조한다.", "eSum": "SAFETY4SEA outlines key measures to prevent rescue boat launching accidents, noting that although rescue boat drills are essential for emergency preparedness, they remain one of the most hazardous routine operations at sea and demand strict inspection and safety-procedure compliance for hooks, davits and falls.", "kImp": "구명·구조정 훈련 전 진수장비 점검과 절차 준수를 표준화하면 훈련 중 인명사고를 예방할 수 있다.", "eImp": "Standardising launching-equipment inspection and procedural discipline before drills helps HSEQ teams prevent casualties during survival-craft operations.", "url": "https://safety4sea.com/key-measures-to-prevent-rescue-boat-launching-accidents-at-sea/"}, {"code": "HSEQ", "title": "New OCIMF guidance aims to ensure safe rollout of TGAIN systems", "src": "SAFETY4SEA", "date": "2026-08-03", "kSum": "석유회사국제해사포럼(OCIMF)이 유럽 내륙수로에서 확산 중인 내륙항행 트랙유도지원시스템(TGAIN, Track Guidance Assistant for Inland Navigation)의 안전한 도입·운용을 위한 새 지침을 발표했다. 시스템의 안전한 채택과 운영을 지원하는 것을 목표로 한다.", "eSum": "OCIMF has issued new guidance to support the safe adoption and operation of Track Guidance Assistant for Inland Navigation (TGAIN) systems as their use expands across Europe's inland waterways.", "kImp": "내륙수로·바지 운항이 포함된 선대의 항행안전 절차와 신규 항행지원시스템 도입 리스크 관리에 참고할 수 있다.", "eImp": "Relevant for HSEQ teams managing inland-waterway/barge operations when integrating new navigation-assistance technology into safe navigation procedures.", "url": "https://safety4sea.com/new-ocimf-guidance-aims-to-ensure-safe-rollout-of-tgain-systems/"}, {"code": "HSEQ", "title": "NorthStandard joins the Dry Bulk Centre of Excellence", "src": "SAFETY4SEA", "date": "2026-08-04", "kSum": "노스스탠다드(NorthStandard)가 P&I 클럽 최초로 드라이벌크 우수센터(Dry Bulk Centre of Excellence, DBCE)에 가입해 벌크선 부문과의 협력을 강화한다고 밝혔다. 더 안전하고 효율적이며 지속가능한 운항을 촉진하기 위한 손실예방 활동 확대의 일환이다.", "eSum": "NorthStandard has become the first P&I club to join the Dry Bulk Centre of Excellence (DBCE), strengthening its engagement with the dry bulk sector as part of wider efforts to promote safer, more efficient and sustainable operations.", "kImp": "벌크선 관리 HSEQ팀은 DBCE 모범사례(화물 액상화·적재 안전 등)와 클럽 손실예방 자료를 활용해 벌크 화물 리스크를 관리할 수 있다.", "eImp": "HSEQ teams managing bulk carriers can leverage DBCE best practices (cargo liquefaction, loading safety) and club loss-prevention material to manage dry bulk cargo risks.", "url": "https://safety4sea.com/northstandard-joins-the-dry-bulk-centre-of-excellence/"}]}, {"code": "KR", "type": "news", "kTitle": "Section 11. 한국 해운시장", "eTitle": "Section 11. Korean Shipping Market", "items": [{"code": "KR", "title": "HMM, 부산서 '2026 어린이 상선체험' 행사 개최", "src": "코리아쉬핑가제트(ksg.co.kr)", "date": "2026-08-07", "kSum": "HMM(에이치엠엠)은 8월 7일 초등학생을 부산으로 초청해 초대형 컨테이너선과 항만 물류 현장을 직접 체험하는 '2026 어린이 상선체험' 행사를 열었다고 밝혔다. 평소 접하기 어려운 해운·항만 현장을 어린이에게 개방해 바다에 대한 꿈을 키워주기 위한 사회공헌 프로그램이다.", "eSum": "HMM said on 7 August it hosted its '2026 Children's Merchant Ship Experience' in Busan, inviting elementary-school children aboard ultra-large container ships and to port logistics sites. The community programme aims to inspire the next generation about the shipping and port industry.", "kImp": "본사 부산 이전을 앞둔 HMM의 지역 밀착형 사회공헌·ESG 행보로, 해운 인력 저변 확대와 부산 해양수도 이미지 제고 측면에서 의미가 있다.", "eImp": "As HMM prepares to relocate its head office to Busan, the community-focused ESG activity supports broadening the shipping talent base and reinforcing Busan's identity as Korea's maritime capital.", "url": "https://www.ksg.co.kr/news/main_newsView.jsp?pNum=147791"}, {"code": "KR", "title": "HD현대, 美 최대 조선사 헌팅턴 잉걸스와 함정 건조 기술 협력 가속", "src": "코리아쉬핑가제트(ksg.co.kr)", "date": "2026-08-07", "kSum": "HD현대(에이치디현대)가 미국 최대 군함 건조업체 헌팅턴 잉걸스(Huntington Ingalls)와 첨단 조선 기술 협력에 속도를 내고 있다. 미국 잉걸스조선소 작업자가 HD현대의 지능형 용접 시스템을 활용해 수평 용접 작업을 수행하는 등 양사 협력이 본격화됐다.", "eSum": "HD Hyundai is accelerating advanced shipbuilding-technology cooperation with Huntington Ingalls, the largest US warship builder. Workers at the US Ingalls yard are now using HD Hyundai's intelligent welding system, marking a deepening of the partnership.", "kImp": "미국의 중국 조선 견제와 함정 MRO·건조 시장 개방 흐름 속에서 K-조선의 미국 방산·상선 시장 진출 교두보로 평가된다.", "eImp": "Amid US moves to curb Chinese shipbuilding and open its naval MRO/newbuild market, the tie-up is seen as a bridgehead for Korean shipbuilders into the US defense and commercial markets.", "url": "https://www.ksg.co.kr/news/main_newsView.jsp?pNum=147793"}, {"code": "KR", "title": "컨테이너 운임지수 4주 만에 반등…美·중동 항로 두 자릿수 상승", "src": "코리아쉬핑가제트(ksg.co.kr)", "date": "2026-08-06", "kSum": "7월 31일자 상하이컨테이너운임지수(SCFI)가 3205.97을 기록하며 4주 만에 반등에 성공했다. 북미·남미·중동 항로 운임이 전주 대비 큰 폭으로 오르며 지수 상승을 견인했다.", "eSum": "The Shanghai Containerized Freight Index (SCFI) rebounded for the first time in four weeks, reaching 3,205.97 as of 31 July. Sharp week-on-week gains on the North America, South America and Middle East routes drove the rise.", "kImp": "성수기 물동량과 중동 지정학 리스크가 맞물려 운임 강세가 재개되는 신호로, HMM 등 국적선사 하반기 실적에 긍정적으로 작용할 전망이다.", "eImp": "With peak-season volumes and Middle East geopolitical risk converging, the rebound signals renewed freight strength, a positive for Korean carriers such as HMM in the second half.", "url": "https://www.ksg.co.kr/news/main_newsView.jsp?pNum=147772"}, {"code": "KR", "title": "HD현대삼호, 머스크에 초대형 암모니아운반선(VLAC) 첫 인도", "src": "코리아쉬핑가제트(ksg.co.kr)", "date": "2026-08-06", "kSum": "HD현대삼호가 회사 역사상 처음으로 9만3000㎥급 초대형 암모니아운반선(VLAC)을 덴마크 선사 머스크(Maersk)에 인도하며 차세대 친환경 선박 시장에서 입지를 다졌다.", "eSum": "HD Hyundai Samho delivered its first-ever 93,000-cbm very large ammonia carrier (VLAC) to Denmark's Maersk, strengthening its position in the next-generation eco-friendly ship market.", "kImp": "무탄소 연료로 주목받는 암모니아 운반선 시장에서 한국 조선의 기술 선도를 입증, 친환경 선박 수주 경쟁력 강화에 기여한다.", "eImp": "The delivery demonstrates Korean yards' technological lead in the ammonia-carrier segment, a zero-carbon fuel focus, bolstering their competitiveness for green-ship orders.", "url": "https://www.ksg.co.kr/news/main_newsView.jsp?pNum=147773"}, {"code": "KR", "title": "해수부 신청사, 부산 북항 1단계 재개발 부지에 건립…2030년 완공", "src": "코리아쉬핑가제트(ksg.co.kr)", "date": "2026-08-06", "kSum": "해양수산부(해수부)는 8월 6일 신청사 건립을 위한 최종 부지로 부산시 동구청이 제안한 북항 1단계 재개발 부지를 선정했다고 밝혔다. 신청사는 2030년 개청을 목표로 한다.", "eSum": "On 6 August the Ministry of Oceans and Fisheries (MOF) selected the Phase 1 North Port redevelopment site proposed by Busan's Dong-gu as the final location for its new headquarters, targeting a 2030 opening.", "kImp": "해수부의 부산 이전이 부지 확정으로 가시화되면서, 부산 해양수도 조성과 공공기관·선사의 부산 집적 흐름이 가속될 전망이다.", "eImp": "With the site confirmed, MOF's relocation to Busan becomes concrete, accelerating Busan's development as a maritime capital and the clustering of public agencies and shipping firms there.", "url": "https://www.ksg.co.kr/news/main_newsView.jsp?pNum=147779"}, {"code": "KR", "title": "HD현대중공업, 그리스 판테온탱커스에 수에즈막스급 원유운반선 인도", "src": "더구루(theguru.co.kr)", "date": "2026-08-09", "kSum": "HD현대중공업이 그리스 선사 판테온탱커스(Pantheon Tankers)가 발주한 15만8000DWT급 수에즈막스 원유운반선 초도선 '씨 토파즈(Sea Topaz)'를 인도했다. 약 1억7600만 달러 규모 2척 계약의 첫 물량으로, 납기를 앞당겨 조기 인도했다.", "eSum": "HD Hyundai Heavy Industries delivered 'Sea Topaz,' the first of two 158,000-dwt Suezmax crude tankers ordered by Greece's Pantheon Tankers. The lead ship of the roughly USD176m contract was handed over ahead of the original schedule.", "kImp": "미국의 중국 조선 제재와 IMO 환경규제로 고품질 한국 신조선 수요가 확대되는 가운데, 범용 유조선 부문에서도 K-조선의 건조 경쟁력을 재확인했다.", "eImp": "As US sanctions on Chinese shipbuilding and tighter IMO rules boost demand for high-quality Korean newbuilds, the delivery reaffirms Korean yards' competitiveness even in the mainstream tanker segment.", "url": "https://www.theguru.co.kr/news/article.html?no=105542"}, {"code": "KR", "title": "한화오션, 계열 한화쉬핑 통해 VLCC 선주사업 본격화…비톨에 3척 장기 용선", "src": "더구루(theguru.co.kr)", "date": "2026-08-08", "kSum": "한화오션이 합작 해운 계열사 한화쉬핑을 앞세워 32만DWT급 VLCC 첫 보유선 '엘란드라 K2'를 인도받고, VLCC 3척을 세계 최대 원유 트레이더 비톨(Vitol)에 장기 용선한다. 선박 건조 중심에서 선박 보유·용선 수익까지 아우르는 밸류체인 다각화 전략이다.", "eSum": "Hanwha Ocean is launching a VLCC owning business through its joint-venture carrier Hanwha Shipping, taking delivery of its first owned vessel, the 320,000-dwt 'Elandra K2,' and chartering three VLCCs long-term to the world's largest oil trader, Vitol, diversifying beyond newbuilding into ship ownership and charter income.", "kImp": "조선사가 선주업으로 사업 영역을 확장하는 전략으로, 안정적 용선 수익 확보와 친환경·스마트십 실증 플랫폼 역할이 기대된다.", "eImp": "The move extends a shipbuilder into ship ownership, promising stable charter income and a testbed for eco-friendly and smart-ship technologies.", "url": "https://www.theguru.co.kr/news/article.html?no=105534"}, {"code": "KR", "title": "HMM, 인도·중동·동아프리카 잇는 신규 'GIA' 컨테이너 서비스 개설", "src": "더구루(theguru.co.kr)", "date": "2026-08-05", "kSum": "HMM(에이치엠엠)이 인도 나바셰바·문드라를 거점으로 탄자니아 다르에스살람, 케냐 몸바사를 연결하는 신규 컨테이너 서비스 'GIA(Gulf–India–East Africa)'를 9월 개설한다. 2800TEU급 5척을 투입하며 중국 코스코, 싱가포르 PIL, 대만 인터아시아라인과 공동 운항한다.", "eSum": "HMM will launch in September a new 'GIA (Gulf–India–East Africa)' container service linking India's Nhava Sheva and Mundra with Dar es Salaam (Tanzania) and Mombasa (Kenya). Five 2,800-TEU ships will be deployed in a joint operation with COSCO, PIL and Interasia Lines.", "kImp": "최원혁 사장의 '허브 앤 스포크' 전략에 따른 두 번째 아프리카 지선망으로, 급성장하는 동아프리카 신흥시장 선점을 위한 포석이다.", "eImp": "The second African feeder network under CEO Choi Won-hyeok's hub-and-spoke strategy, it positions HMM to capture the fast-growing East African emerging market.", "url": "https://www.theguru.co.kr/news/article.html?no=105380"}, {"code": "KR", "title": "장금마리타임과 합병 앞둔 MSC, 에너지 해운 포트폴리오 확대", "src": "더구루(theguru.co.kr)", "date": "2026-08-05", "kSum": "장금상선과 유조선 사업 공동경영을 준비 중인 MSC(엠에스씨)가 VLCC 등 선대 160척 이상을 확보하며 컨테이너 의존도를 낮추는 '투트랙' 전략을 편다. MSC는 장금마리타임 지분 50%(약 7350억원)를 인수하며, 현재 공정거래위원회가 기업결합을 심사 중이다.", "eSum": "MSC, preparing to jointly run a tanker business with Korea's Sinokor (Jangkeum), is pursuing a two-track strategy to reduce container dependence by securing a fleet of over 160 ships including VLCCs. MSC is acquiring a 50% stake in Jangkeum Maritime (about KRW735bn), a deal now under Korea Fair Trade Commission review.", "kImp": "세계 최대 컨테이너선사의 유조선 시장 진출과 국적 선사 장금상선의 합작으로, VLCC 용선시장의 경쟁 구조 변화가 주목된다.", "eImp": "The world's largest container carrier's push into tankers via a JV with Korea's Sinokor draws attention to potential shifts in the VLCC charter market's competitive structure.", "url": "https://www.theguru.co.kr/news/article.html?no=105389"}]}, {"code": "INS", "type": "news", "kTitle": "Section 12. 해상보험 (H&M)", "eTitle": "Section 12. Marine Insurance (H&M)", "items": [{"code": "INS", "title": "흑해서 러시아 공격에 선원 1명 사망…선체 전쟁위험 요율 상승", "src": "Insurance Marine News", "date": "2026-08-07", "kSum": "흑해에서 화물선 메라 퀸(Mera Queen, IMO 9664108)이 러시아의 공격을 받아 선원 1명이 사망하고 3명이 부상했다. 이 사건 이후 흑해 항행 선박의 선체(H&M) 전쟁위험 보험료율이 상승하고 있다.", "eSum": "One sailor was killed and three injured in a Russian strike on the cargo vessel Mera Queen (IMO 9664108) in the Black Sea. Following the attack, hull (H&M) war-risk rates for vessels trading in the Black Sea are rising.", "kImp": "흑해 전쟁위험 구역 확대와 요율 급등이 지속되며 곡물·에너지 화물의 흑해 운송 비용과 선주 부담이 커지고 있다.", "eImp": "Widening Black Sea war-risk zones and surging rates continue to raise transport costs for grain and energy cargoes and increase owners' exposure.", "url": "https://insurancemarinenews.com/insurance-marine-news/sailor-killed-in-russian-strike-hull-war-rates-rise-in-black-sea/"}, {"code": "INS", "title": "후티, 사우디 유조선 공격 주장…걸프 통항량 급감", "src": "Insurance Marine News", "date": "2026-08-07", "kSum": "후티(Houthi)가 사우디 연계 유조선 공격을 주장한 뒤, 8월 5일 호르무즈 해협과 바브엘만데브 해협의 상선 통항량이 전일 대비 크게 감소한 것으로 나타났다.", "eSum": "After Houthi forces claimed an attack on a Saudi-linked tanker, shipping traffic through the Strait of Hormuz and the Bab-al-Mandab strait fell significantly on Wednesday 5 August compared with the previous day.", "kImp": "홍해·걸프 지정학 리스크가 재고조되며 전쟁위험 추가보험료(AP)와 우회 압력이 커져 해상보험·물류비 부담이 확대되고 있다.", "eImp": "Renewed Red Sea and Gulf geopolitical risk drives up war-risk additional premiums and rerouting pressure, adding to marine insurance and logistics costs.", "url": "https://insurancemarinenews.com/insurance-marine-news/gulf-shipping-traffic-down-after-houthis-say-they-attacked-saudi-tanker/"}, {"code": "INS", "title": "후티, 아덴만서 사우디 연계 제품운반선 미사일 공격 주장", "src": "Insurance Marine News", "date": "2026-08-07", "kSum": "후티(Houthi) 세력이 아덴만을 통과하던 사우디 연계 화학/석유제품 운반선 데이지(Daisy, IMO 9516545)를 미사일로 공격했다고 주장했다.", "eSum": "Houthi forces said they struck the Saudi-linked chemical/oil products tanker Daisy (IMO 9516545) with a missile while it was transiting the Gulf of Aden.", "kImp": "홍해·아덴만 상선 공격이 재개되면서 해당 해역의 전쟁위험 보험 요율과 담보 조건이 강화될 전망이다.", "eImp": "With attacks on merchant ships resuming in the Red Sea and Gulf of Aden, war-risk rates and cover terms for the area are set to tighten.", "url": "https://insurancemarinenews.com/insurance-marine-news/houthis-claim-missile-attack-on-saudi-linked-products-tanker-in-gulf-of-aden/"}, {"code": "INS", "title": "이란 '오만과 호르무즈 합의 원칙적 타결' 주장", "src": "Insurance Marine News", "date": "2026-08-07", "kSum": "이란이 호르무즈 해협 관련 오만과의 합의가 '원칙적으로' 타결됐다고 주장했다. 다만 8월 5일 발표 약속에도 목요일 아침까지 공식 발표는 나오지 않았다.", "eSum": "Iran claimed a deal on the Strait of Hormuz had been 'agreed in principle' with Oman. However, despite promises of an announcement on Wednesday 5 August, none had been made by Thursday morning.", "kImp": "호르무즈 긴장 완화 기대와 불확실성이 교차하며, 전쟁위험 보험료율의 방향성에 직접적 영향을 미친다.", "eImp": "Hopes of de-escalation at Hormuz mixed with continued uncertainty bear directly on the direction of war-risk premium rates.", "url": "https://insurancemarinenews.com/insurance-marine-news/iran-oman-deal-on-hormuz-agreed-in-principle-iran-claims/"}, {"code": "INS", "title": "국제 해운단체 8곳, IMO·유엔에 호르무즈 자유항행 보장 요청", "src": "Insurance Marine News", "date": "2026-08-07", "kSum": "세계 주요 국제 해운단체 8곳이 유엔 사무총장과 IMO 사무총장에게 호르무즈 해협의 자유항행 보장을 촉구하는 공동 서한을 보냈다.", "eSum": "Eight major international shipping trade associations sent a joint letter to the UN Secretary-General and the IMO Secretary-General urging that free passage be ensured at the Strait of Hormuz.", "kImp": "업계 차원의 항행 안전 압박으로, 걸프 해역 위험 완화와 선원 보호·해상보험 안정화 요구가 커지고 있음을 보여준다.", "eImp": "The industry-wide push underscores mounting calls to reduce Gulf risk and to protect seafarers and stabilise marine insurance markets.", "url": "https://insurancemarinenews.com/insurance-marine-news/eight-international-shipping-associations-ask-imo-and-un-to-ensure-free-passage-at-strait-of-hormuz/"}, {"code": "INS", "title": "HIVE 언더라이터스, 신임 적하보험 총괄 선임…해상보험 강화", "src": "Insurance Marine News", "date": "2026-08-07", "kSum": "독립 스페셜티 MGA인 HIVE 언더라이터스(HIVE Underwriters)가 폴리 메이스(Polly Mays)를 적하보험(Cargo) 총괄로 선임하며 해상보험 부문 인수 역량을 강화했다.", "eSum": "Independent specialty MGA HIVE Underwriters has appointed Polly Mays as Head of Cargo, strengthening its marine division and expanding its underwriting capabilities.", "kImp": "적하보험 언더라이팅 역량 확충 움직임으로, 지정학·공급망 리스크 확대 속 화물보험 수요 대응이 강화되고 있다.", "eImp": "The hire reflects a build-up of cargo underwriting capacity, responding to rising cargo-insurance demand amid geopolitical and supply-chain risks.", "url": "https://insurancemarinenews.com/insurance-marine-news/hive-underwriters-strengthens-marine-team-with-new-head-of-cargo/"}, {"code": "INS", "title": "안타레스 글로벌, 새 경영 체제 발표", "src": "Insurance Marine News", "date": "2026-08-07", "kSum": "스페셜티 보험·재보험 그룹 안타레스 글로벌(Antares Global)이 마이클 판 데르 스트라텐(Michael van der Straaten) 전 최고경영자의 별세 이후 새로운 리더십 구조를 발표했다.", "eSum": "Specialty insurance and reinsurance group Antares Global has announced a new leadership structure following the untimely death of its former CEO, Michael van der Straaten.", "kImp": "주요 런던 스페셜티 마켓 참여사의 리더십 개편으로, 해상보험 인수 전략의 연속성에 관심이 모아진다.", "eImp": "The leadership reshuffle at a key London specialty market player draws attention to continuity in its marine underwriting strategy.", "url": "https://insurancemarinenews.com/insurance-marine-news/antares-global-announces-new-leadership-structure/"}, {"code": "INS", "title": "해상보험 주간 종합(8월 7일자)…차나칼레 해협 통항 중 유조선 화재", "src": "Insurance Marine News", "date": "2026-08-07", "kSum": "8월 5일 튀르키예 차나칼레 해협을 통항하던 아스팔트/비투멘 운반선 하브바 아나(Havva Ana, IMO 9997385)에서 현지시간 05:30 화재가 발생했으나 인명피해는 없었다. 이 밖의 주간 해상 사고·손해 동향을 종합했다.", "eSum": "On 5 August the asphalt/bitumen tanker Havva Ana (IMO 9997385) caught fire while transiting Türkiye's Canakkale Strait at 05:30 local time, with no injuries. The round-up compiles the week's marine casualties and losses.", "kImp": "선체·적하보험 클레임과 직결되는 주간 사고 동향으로, 주요 해협 통항 리스크와 손해율 관리 필요성을 부각한다.", "eImp": "The weekly casualty round-up, directly relevant to hull and cargo claims, highlights strait-transit risk and the need for loss-ratio management.", "url": "https://insurancemarinenews.com/insurance-marine-news/marine-round-up-7th-august-2026/"}, {"code": "INS", "title": "파나마운하 수위 하락에 흘수 제한 강화", "src": "Insurance Marine News", "date": "2026-08-07", "kSum": "강력한 엘니뇨 우려 속에 파나마운하 수위가 낮아지면서 흘수(draft) 제한이 강화됐다. 유럽 하천 수위 저하와 함께 물류 차질 우려가 제기됐다.", "eSum": "Amid concerns over an unusually strong El Nino, falling water levels in the Panama Canal have led to tighter draft limits, adding to logistics-disruption worries alongside low European river levels.", "kImp": "흘수·통항 제한은 화물 적재량 감소와 운송 지연으로 이어져 적하·운송 리스크와 관련 비용에 영향을 미친다.", "eImp": "Draft and transit restrictions cut cargo intake and cause delays, affecting cargo/transit risk and associated costs.", "url": "https://insurancemarinenews.com/insurance-marine-news/water-levels-fall-in-panama-canal-draft-limits-tightened/"}]}, {"code": "PNI", "type": "news", "kTitle": "Section 13. P&I 클럽", "eTitle": "Section 13. P&I Clubs", "items": [{"code": "PNI", "title": "웨스트(West P&I), 2025/26 연차보고서서 '견조한 재무 성과' 강조", "src": "Insurance Marine News", "date": "2026-08-07", "kSum": "그룹 클럽 웨스트(West)는 2025/26 전체 재무보고서에서 최근 풀(Pool) 실적과 다각화된 사업모델이 견조한 재무성과를 뒷받침했다고 밝혔다.", "eSum": "In its full 2025/26 financial report, Group Club West said recent Pool performance and its diversified model had supported a strong financial result.", "kImp": "주요 P&I 클럽의 안정적 실적은 2026 갱신기의 요율 및 재무건전성 흐름을 가늠하는 지표로 활용된다.", "eImp": "A stable result from a major P&I club serves as a gauge of rating trends and financial resilience heading into the 2026 renewal.", "url": "https://insurancemarinenews.com/insurance-marine-news/wests-full-report-for-2025-26-cites-strong-financial-performance/"}, {"code": "PNI", "title": "인도, 자국 P&I 보험상품 출범…국제시장 의존도 완화", "src": "SAFETY4SEA", "date": "2026-08-03", "kSum": "인도가 국제 해상보험 시장 의존도를 낮추기 위해 정부가 뒷받침하는 자국 P&I(선주상호보험) 상품을 출범시키며 해상보험 지형에 새로운 국면을 열었다.", "eSum": "India has launched a sovereign-backed Protection and Indemnity (P&I) insurance product aimed at reducing the sector's reliance on international insurance markets, marking a new phase for its marine insurance landscape.", "kImp": "신흥 해운국의 자국 P&I 구축 움직임으로, 국제그룹(IG) 중심의 P&I 시장 구조에 장기적 변화 가능성을 시사한다.", "eImp": "An emerging maritime nation building its own P&I capacity signals possible long-term change to the IG-centric structure of the P&I market.", "url": "https://safety4sea.com/indias-maritime-sector-gains-domestic-insurance-shield-with-pi-initiative/"}]}, {"code": "VET", "type": "news", "kTitle": "Section 14. 베팅·검사", "eTitle": "Section 14. Vetting & Inspection", "items": [{"code": "VET", "title": "최근 7일간 신규 소식이 확인되지 않았습니다", "src": "—", "date": "2026-08-09", "kSum": "이 기간 해당 분야의 신선한 기사가 확인되지 않았습니다. 다음 갱신 시 보완됩니다.", "eSum": "No fresh items were confirmed in this category over the last 7 days; it will be updated in the next cycle.", "kImp": "-", "eImp": "-", "url": "https://brightatsea-alt.github.io/maritime-daily-digest/"}]}, {"code": "CLASS", "type": "news", "kTitle": "Section 15. 선급", "eTitle": "Section 15. Classification Societies", "items": [{"code": "CLASS", "title": "ClassNK issues Technical Information TEC-1379 on Tokyo MoU / Paris MoU Joint CIC on Cargo Securing", "src": "ClassNK", "date": "2026-08-07", "kSum": "일본 선급 클래스엔케이(ClassNK)는 8월 7일 기술정보(Technical Information) TEC-1379를 발행하여, 도쿄 MoU와 파리 MoU가 화물 고박(Cargo Securing)을 대상으로 하는 공동 집중점검 캠페인(CIC) 시행을 발표했음을 회원사에 안내했다. 해당 CIC는 2026년 9월 1일부터 11월 30일까지 실시된다. 클래스엔케이는 관련 세부 사항과 각 MoU의 공식 발표 링크를 함께 제공했다.", "eSum": "Classification society ClassNK issued Technical Information TEC-1379 on 7 August 2026, informing members that the Tokyo MoU and Paris MoU on Port State Control have announced a joint Concentrated Inspection Campaign (CIC) focused on Cargo Securing. The campaign will run from 1 September to 30 November 2026. ClassNK provided details and links to the respective MoU announcements.", "kImp": "선급이 화물 고박 대상 PSC 집중점검 캠페인을 사전 안내함으로써 선사들이 9~11월 검사 강화에 대비할 수 있도록 지원한다는 점에서 의의가 있다.", "eImp": "The circular gives shipowners advance notice to prepare for intensified PSC scrutiny of cargo securing during the September-November 2026 campaign.", "url": "https://www.classnk.or.jp/hp/en/tech_info/tech_main.aspx?techno=1379"}]}, {"code": "COMM", "type": "news", "kTitle": "Section 16. 상업·용선시장", "eTitle": "Section 16. Commercial & Chartering", "items": [{"code": "COMM", "title": "Transpacific container rates rally as Europe's peak season fades", "src": "gcaptain", "date": "2026-08-07", "kSum": "태평양 횡단 항로 컨테이너 스팟운임이 반등한 반면, 유럽 항로는 4주 연속 하락하며 성수기 효과가 소멸됐다. 선사들은 유럽 노선에서 운임 인상 계획을 취소·축소하고 있다.", "eSum": "Transpacific container spot rates rallied while European trades fell for a fourth straight week as carriers cancelled or scaled back rate hikes, signalling a fading peak season on Europe routes.", "kImp": "주요 컨테이너 항로 간 운임 방향이 엇갈리며 하반기 성수기 강도에 대한 불확실성이 커지고 있음을 시사한다.", "eImp": "Diverging rate trends across major container trades point to an uncertain second-half peak season.", "url": "https://gcaptain.com/transpacific-container-rates-rally-as-europes-peak-season-fades/"}, {"code": "COMM", "title": "US container import peak winds down after tariff-driven rush", "src": "gcaptain", "date": "2026-08-07", "kSum": "미국의 컨테이너 수입 조기 성수기가 마무리 국면에 접어들었다. 소매업체들이 신규 관세 시행 전 물량을 앞당겨 들여오며 상반기 수입이 급증했으나, 그 반동으로 하반기 물량 둔화가 예상된다.", "eSum": "The early US container import peak is winding down after retailers front-loaded shipments to beat new tariffs, with a slowdown now expected in the second half.", "kImp": "관세發 선(先)수입 러시가 끝나면서 미국 수입 물동량과 태평양 항로 운임에 하방 압력이 커질 전망이다.", "eImp": "The end of the tariff-driven front-loading points to softening US import volumes and downward pressure on transpacific rates.", "url": "https://gcaptain.com/u-s-container-import-peak-winds-down-after-tariff-driven-rush/"}, {"code": "COMM", "title": "ENEOS to acquire TPC Group including Port Neches terminal", "src": "splash247", "date": "2026-08-08", "kSum": "일본 에너지기업 에네오스(ENEOS)가 미국 TPC 그룹을 인수하기로 했다. 텍사스 포트 네체스(Port Neches) 터미널이 포함된 거래로, 에네오스의 화학·물류 자산 확대 전략의 일환이다.", "eSum": "Japan's ENEOS is to acquire US-based TPC Group, including its Port Neches terminal in Texas, expanding its chemical and logistics asset base.", "kImp": "터미널을 포함한 에너지·화학 M&A는 일본 기업의 미국 물류 인프라 확보 흐름을 보여주며 항만·화물 밸류체인 재편과 연결된다.", "eImp": "An energy-chemical M&A with a terminal underscores Japanese firms securing US logistics infrastructure.", "url": "https://splash247.com/eneos-to-acquire-tpc-group-including-port-neches-terminal/"}, {"code": "COMM", "title": "Bruton lands six-figure rate for second new VLCC", "src": "splash247", "date": "2026-08-06", "kSum": "토르 올라브 트로임(Tor Olav Trøim)이 후원하는 브루튼(Bruton)이 두 번째 VLCC 신조선을 일 10만5,700달러의 순 용선료로 확정했다. 강세인 대형 원유탱커 용선시장을 방증한다.", "eSum": "Tor Olav Trøim-backed Bruton has fixed its second VLCC newbuilding at a net rate of $105,700 per day, underscoring a strong large crude tanker charter market.", "kImp": "6자릿수 VLCC 용선료 확정은 대형 원유탱커 시장의 강세와 장기 용선 수요의 견조함을 보여주는 신호다.", "eImp": "A six-figure VLCC charter fixture signals robust large crude tanker demand and firm long-term rates.", "url": "https://splash247.com/bruton-lands-six-figure-rate-for-second-new-vlcc/"}, {"code": "COMM", "title": "Frontline strikes $270m deal for VLCC pair", "src": "splash247", "date": "2026-08-05", "kSum": "존 프레드릭센(John Fredriksen)의 프론트라인(Frontline)이 2017년 건조 VLCC 2척을 2억7,000만 달러(척당 1억3,500만 달러)에 매각했다. 강세인 탱커 자산가치를 활용한 차익 실현 거래다.", "eSum": "John Fredriksen's Frontline has agreed to sell two 2017-built VLCCs for $270m ($135m each), cashing in on firm tanker asset values.", "kImp": "고가 중고선 매각은 탱커 자산가치 고점 국면과 선주들의 차익 실현 움직임을 보여주는 대표적 S&P 사례다.", "eImp": "A premium secondhand sale exemplifies peak tanker asset values and owners realising gains.", "url": "https://splash247.com/frontline-strikes-270m-deal-for-vlcc-pair/"}]}, {"code": "GEO", "type": "news", "kTitle": "Section 17. 지정학", "eTitle": "Section 17. Geopolitics", "items": [{"code": "GEO", "title": "Black Sea attacks choke grain, coal and iron ore trades", "src": "splash247", "date": "2026-08-05", "kSum": "러시아가 우크라이나 항만 인프라와 선박 4척에 대한 공격을 주장하면서 흑해가 세계에서 가장 위험한 해역으로 부상했다. 곡물·석탄·철광석 교역이 심각하게 위축되고 있다.", "eSum": "Russia claimed strikes on four vessels and port infrastructure in Ukraine, turning the Black Sea into one of the world's most dangerous waters and choking grain, coal and iron ore trades.", "kImp": "흑해 교역 차질은 곡물·벌크 공급망과 전쟁위험보험료(war risk)를 압박하며 글로벌 식량·원자재 물류에 파급된다.", "eImp": "Black Sea disruption pressures bulk supply chains and war-risk premiums, rippling into global food and commodity flows.", "url": "https://splash247.com/black-sea-attacks-choke-grain-coal-and-iron-ore-trades/"}, {"code": "GEO", "title": "Rosatom says seven Chinese vessels will sail to Europe via Russia's Arctic route", "src": "gcaptain", "date": "2026-08-07", "kSum": "러시아 국영 로사톰(Rosatom)이 북극항로(NSR)를 통한 중국 선박 7척의 유럽행 통항 허가를 발급했다고 밝혔다. 중·러 간 북극 물류 협력 강화 신호다.", "eSum": "Russia's Rosatom said it issued permits for seven Chinese vessels to transit to Europe via the Northern Sea Route, signalling deepening Sino-Russian Arctic logistics ties.", "kImp": "북극항로를 통한 중·러 협력은 서방 제재 국면에서 대체 교역로 구축과 지정학적 진영화를 보여준다.", "eImp": "Sino-Russian use of the NSR reflects alternative trade-route building and geopolitical bloc alignment amid Western sanctions.", "url": "https://gcaptain.com/rosatom-says-seven-chinese-vessels-will-sail-to-europe-via-russias-arctic-route/"}, {"code": "GEO", "title": "Dozens of idling Iranian oil tankers show US blockade is working", "src": "gcaptain", "date": "2026-08-05", "kSum": "이란 연안에 유조선들이 대거 정박·대기하는 정황이 포착됐다. 미국의 재개된 해상 봉쇄가 이란의 에너지 수출을 실질적으로 옥죄고 있음을 보여주는 신호로 해석된다.", "eSum": "A growing flotilla of idling Iranian oil tankers off the country's coast indicates that the renewed US naval blockade is disrupting Tehran's energy exports.", "kImp": "이란산 원유 수출 차질은 글로벌 원유 공급과 유가, 그림자 선단 흐름에 영향을 주는 핵심 지정학 변수다.", "eImp": "Disrupted Iranian exports are a key geopolitical driver of global crude supply, oil prices and shadow-fleet flows.", "url": "https://gcaptain.com/dozens-of-idling-iranian-oil-tankers-show-us-blockade-is-working/"}, {"code": "GEO", "title": "White House expected to extend controversial Jones Act waiver", "src": "gcaptain", "date": "2026-08-04", "kSum": "백악관이 100년 넘은 존스법(Jones Act)의 면제를 연장할 것으로 예상된다. 에너지 공급 안정을 위해 자국 선박 운송 요건을 한시적으로 완화하는 조치로 논란이 크다.", "eSum": "The White House is expected to extend a waiver of the century-old Jones Act, temporarily easing US-flag shipping requirements to shore up energy supply, drawing controversy.", "kImp": "존스법 면제 연장은 미국 연안 해운 정책과 자국 선대 보호 기조에 균열을 시사하며 업계 논쟁을 촉발한다.", "eImp": "Extending the Jones Act waiver signals strain in US cabotage policy and reignites industry debate over domestic fleet protection.", "url": "https://gcaptain.com/white-house-expected-to-extend-controversial-jones-act-waiver-sources-say/"}]}, {"code": "TW", "type": "news", "kTitle": "Section 18. TradeWinds 선박관리", "eTitle": "Section 18. TradeWinds Ship Management", "items": [{"code": "TW", "title": "Diana Shipping nets pay rise from new capesize deal with NYK", "src": "TradeWinds", "date": "2026-08-07", "kSum": "다이애나 시핑(Diana Shipping)이 일본 NYK와 체결한 새로운 케이프사이즈 벌크선 계약으로 용선료 인상을 확보했다고 TradeWinds가 전했다. 헤드라인 기준 기존 대비 개선된 수익 조건이 핵심이다.", "eSum": "TradeWinds reports Diana Shipping has secured a pay rise through a new capesize charter deal with Japan's NYK. Per the headline, the fresh contract improves the owner's earnings on the vessel.", "kImp": "벌크선주의 케이프사이즈 용선료 개선은 건화물 시황 회복 신호로 해석될 수 있다.", "eImp": "Improved capesize charter terms signal a firming dry bulk market for owners.", "url": "https://www.tradewindsnews.com/bulkers/diana-shipping-nets-pay-rise-from-new-capesize-deal-with-nyk/2-1-2026495"}, {"code": "TW", "title": "Maersk to divest training unit in deal with OpenGate Capital", "src": "TradeWinds", "date": "2026-08-07", "kSum": "머스크(Maersk)가 사모펀드 오픈게이트 캐피털(OpenGate Capital)과의 거래를 통해 자사 교육·훈련 사업부를 매각한다고 TradeWinds가 보도했다. 헤드라인 기준 비핵심 자산 정리 성격의 거래로 보인다.", "eSum": "TradeWinds reports Maersk is divesting its training unit in a deal with OpenGate Capital. The headline frames it as a sale of a non-core business to a private equity buyer.", "kImp": "대형 선사의 교육 사업부 매각은 선원 훈련 서비스 시장 재편 가능성을 시사한다.", "eImp": "A major carrier selling its training arm hints at reshaping of the seafarer-training services market.", "url": "https://www.tradewindsnews.com/containers/maersk-to-divest-training-unit-in-deal-with-opengate-capital/2-1-2026550"}, {"code": "TW", "title": "Return of El Nino could provide tailwinds for Genco and dry bulk trade", "src": "TradeWinds", "date": "2026-08-07", "kSum": "엘니뇨(El Nino)의 재등장이 젠코 시핑(Genco Shipping)과 건화물 무역에 우호적으로 작용할 수 있다고 TradeWinds가 전했다. 헤드라인 기준 기상 변화가 벌크 물동량에 순풍이 될 수 있다는 전망이다.", "eSum": "TradeWinds reports the return of El Nino could provide tailwinds for Genco Shipping and dry bulk trade. Per the headline, the weather pattern may support bulk cargo demand.", "kImp": "기상 변수는 벌크선주의 물동량과 운임 전망에 영향을 줄 수 있다.", "eImp": "Weather patterns like El Nino can shift cargo volumes and rate outlooks for bulker owners.", "url": "https://www.tradewindsnews.com/bulkers/return-of-el-nino-could-provide-tailwinds-for-genco-and-dry-bulk-trade/2-1-2026566"}, {"code": "TW", "title": "Peter Georgiopoulos-backed SeaArctos slams state of emissions monitoring", "src": "TradeWinds", "date": "2026-08-07", "kSum": "피터 게오르기오풀로스(Peter Georgiopoulos)가 후원하는 씨아크토스(SeaArctos)가 현행 선박 배출 모니터링 체계의 미흡함을 강하게 비판했다고 TradeWinds가 보도했다. 헤드라인 기준 배출 측정·감시의 신뢰성 문제를 제기한 것이다.", "eSum": "TradeWinds reports SeaArctos, backed by Peter Georgiopoulos, has slammed the current state of emissions monitoring. The headline points to concerns over the reliability of emissions measurement and oversight.", "kImp": "배출 모니터링 신뢰성 논란은 선주의 규제 대응과 데이터 관리 부담을 키울 수 있다.", "eImp": "Doubts over emissions monitoring could increase owners' compliance and data-management burden.", "url": "https://www.tradewindsnews.com/sustainability/peter-georgiopoulos-backed-seaarctos-slams-state-of-emissions-monitoring/2-1-2026304"}, {"code": "TW", "title": "Container shipping market shows 'resilience' as volumes climb", "src": "TradeWinds", "date": "2026-08-07", "kSum": "컨테이너 해운 시장이 물동량 증가와 함께 '회복력'을 보이고 있다고 TradeWinds가 전했다. 헤드라인 기준 수요 증가가 시장의 견조함을 뒷받침하고 있다는 진단이다.", "eSum": "TradeWinds reports the container shipping market is showing 'resilience' as volumes climb. Per the headline, rising demand is underpinning market strength.", "kImp": "컨테이너 물동량 회복은 선사·선주의 운임과 수익 전망을 개선할 수 있다.", "eImp": "Recovering container volumes could improve rate and earnings prospects for carriers and owners.", "url": "https://www.tradewindsnews.com/containers/container-shipping-market-shows-resilience-as-volumes-climb/2-1-2026359"}, {"code": "TW", "title": "'We'll find you': Shadow fleet master claims he was threatened before ship boarding", "src": "TradeWinds", "date": "2026-08-07", "kSum": "그림자 선단(shadow fleet) 소속 선박의 선장이 승선·검문 전 협박을 받았다고 주장했다고 TradeWinds가 보도했다. 헤드라인 기준 'We'll find you(너를 찾아내겠다)'라는 위협을 받았다는 내용이다.", "eSum": "TradeWinds reports a shadow fleet master claims he was threatened, told 'we'll find you', before his ship was boarded. The headline centres on alleged intimidation of the vessel's master.", "kImp": "그림자 선단 단속 과정의 선원 안전 문제는 선박관리·크루잉 리스크를 부각한다.", "eImp": "Crew-safety concerns during shadow-fleet enforcement highlight ship-management and crewing risks.", "url": "https://www.tradewindsnews.com/tankers/-we-ll-find-you-shadow-fleet-master-claims-he-was-threatened-before-ship-boarding/2-1-2026459"}, {"code": "TW", "title": "BW LNG poised to send LNG steam ship to China for FSRU conversion job", "src": "TradeWinds", "date": "2026-08-07", "kSum": "BW LNG가 노후 LNG 스팀선을 FSRU(부유식 저장·재기화 설비)로 개조하기 위해 중국으로 보낼 준비를 하고 있다고 TradeWinds가 전했다. 헤드라인 기준 선주의 자산 재활용·개조 프로젝트다.", "eSum": "TradeWinds reports BW LNG is poised to send an LNG steam ship to China for an FSRU conversion job. Per the headline, it is an owner's asset conversion and reuse project.", "kImp": "노후 LNG선의 FSRU 개조는 선주의 선대 자산 활용 전략을 보여준다.", "eImp": "Converting an ageing LNG carrier to an FSRU shows how owners are repurposing fleet assets.", "url": "https://www.tradewindsnews.com/gas/bw-lng-poised-send-lng-steam-ship-to-china-for-fsru-conversion-job/2-1-2026279"}]}, {"code": "HOT", "type": "news", "kTitle": "Section 19. 핫이슈: 호르무즈 해협", "eTitle": "Section 19. Hot Topic: Strait of Hormuz", "items": [{"code": "HOT", "title": "UAE says Iran attacked vessel with missile in Strait of Hormuz", "src": "gcaptain", "date": "2026-08-08", "kSum": "아랍에미리트(UAE)가 8일 자국 국영 석유회사와 연계된 선박이 호르무즈 해협에서 이란의 미사일 공격을 받았다고 규탄했다. 해협 내 긴장이 실제 무력 충돌로 비화하고 있음을 보여준다.", "eSum": "The UAE on Saturday condemned what it said was an Iranian missile attack on a carrier linked to its state oil company in the Strait of Hormuz.", "kImp": "국가 배후 공격 주장은 호르무즈 위기가 외교 국면을 넘어 직접적 군사 충돌로 확대될 위험을 부각한다.", "eImp": "An alleged state-backed strike raises the risk of the Hormuz crisis escalating from diplomacy into direct military confrontation.", "url": "https://gcaptain.com/uae-says-iran-attacked-vessel-with-missile-in-strait-of-hormuz/"}, {"code": "HOT", "title": "Iran debates Hormuz wording as Trump says deal's 'moving along'", "src": "gcaptain", "date": "2026-08-07", "kSum": "이란 의회가 오만과의 호르무즈 해협 관련 합의문 문구를 놓고 논의 중인 가운데, 트럼프 미 대통령은 협상이 '진전되고 있다'고 밝혔다. 협상과 긴장이 병존하는 국면이다.", "eSum": "Iranian lawmakers are debating the wording of a proposed Hormuz deal with Oman, with President Trump insisting the negotiations are 'moving along'.", "kImp": "합의 문구를 둘러싼 협상 진통은 호르무즈 통항 체제의 향방과 해운·유가 불확실성을 좌우하는 핵심 변수다.", "eImp": "Wrangling over the deal's wording is the pivotal variable shaping Hormuz transit rules and shipping-oil uncertainty.", "url": "https://gcaptain.com/iran-debates-hormuz-wording-as-trump-says-deals-moving-along/"}, {"code": "HOT", "title": "Vessel traffic through Hormuz dwindles this week as markets watch Iran-Oman talks", "src": "gcaptain", "date": "2026-08-07", "kSum": "호르무즈 해협 통항 선박이 월~목 33척으로 급감했다. 직전 주 같은 기간 50척 대비 크게 줄어든 수치로, 이란-오만 협상을 지켜보며 선사들이 통항을 꺼리고 있다.", "eSum": "Shipping traffic through the Strait of Hormuz dwindled to 33 vessels Monday-Thursday, down from 50 in the prior week, as owners await Iran-Oman talks.", "kImp": "통항량 급감은 세계 최대 원유 수송 관문의 실질적 위축을 수치로 보여주며 공급 차질과 유가 상방 압력을 시사한다.", "eImp": "A sharp drop in transits quantifies the real contraction of the world's key oil chokepoint, signalling supply strain and upward oil-price pressure.", "url": "https://gcaptain.com/vessel-traffic-through-hormuz-dwindles-this-week-as-markets-watch-iran-oman-talks/"}]}, {"code": "SYS", "type": "news", "kTitle": "Section 20. 시스템·앱", "eTitle": "Section 20. System & App", "items": [{"code": "SYS", "title": "Dualog, 선주 운영에 맞춘 Workspace로 이메일 과부하 공략", "src": "The Digital Ship", "date": "2026-08-03", "kSum": "노르웨이 해사 IT 기업 두알로그(Dualog)가 선주·선박관리 운영에 특화한 협업 솔루션 'Workspace'를 출시했다. 설문상 선원의 약 44%가 넘치는 수신함을 주요 불만으로 꼽고 70%는 이미 업무에 왓츠앱(WhatsApp)을 사용하는 현실을 겨냥해, 분산된 커뮤니케이션을 하나의 안전한 업무 환경으로 통합하는 것이 목표다.", "eSum": "Norwegian maritime IT firm Dualog has launched 'Workspace', a collaboration tool purpose-built for shipowner and ship-management operations. It targets email overload, citing that around 44% of seafarers name overloaded inboxes as a leading frustration and 70% already use WhatsApp for work, aiming to consolidate fragmented communications into a single secure operational environment.", "kImp": "선박-육상 간 커뮤니케이션 분산 문제를 겨냥한 전용 협업 플랫폼으로 선주 운영 효율화가 기대된다.", "eImp": "A dedicated collaboration platform aimed at fragmented ship-shore communication could streamline shipowner operations.", "url": "https://thedigitalship.com/news/maritime-software/dualog-targets-email-overload-with-workspace-built-for-shipowner-operations/"}, {"code": "SYS", "title": "제로노스, 해운 운영용 에이전틱 AI 파트너 'Propel' 공개", "src": "Manifold Times", "date": "2026-08-05", "kSum": "해사 기술 기업 제로노스(ZeroNorth)가 8월 4일 해운 운영을 위한 에이전틱 AI 파트너 'Propel by ZeroNorth'를 선보였다. AI 에이전트가 항해 최적화 관련 반복 수작업을 대신 처리해 항해 계획 수립, 선장과의 커뮤니케이션 관리, 피드백 반영·계획 갱신을 운영자를 배제하지 않고 자동화한다. 현재 카길(Cargill), 울트라벌크(Ultrabulk), CMB.TECH 등 주요 고객에 얼리액세스로 제공되며 광범위한 상용화는 2026년 후반으로 예정됐다.", "eSum": "Maritime technology firm ZeroNorth on 4 August unveiled 'Propel by ZeroNorth', an agentic AI partner for maritime operations. AI agents take on repetitive manual voyage-optimisation tasks, generating voyage plans, managing communication with the master and incorporating feedback while keeping operators in the loop. It is now in early access with key customers Cargill, Ultrabulk and CMB.TECH, with wider commercial availability planned for later in 2026.", "kImp": "인사이트 제공을 넘어 실제 실행까지 담당하는 에이전틱 AI가 해운 운영 자동화의 새 국면을 연다.", "eImp": "Agentic AI that acts rather than merely advises signals a new phase in automating maritime operations.", "url": "https://www.manifoldtimes.com/news/zeronorth-debuts-new-agentic-ai-partner-for-maritime-operations/"}, {"code": "SYS", "title": "클라이페다 컨테이너 터미널, Portchain Quay 선석계획 SW 도입", "src": "Container News", "date": "2026-08-06", "kSum": "리투아니아 클라이페다 컨테이너 터미널(KCT)이 포트체인(Portchain)의 'Quay' 선석계획 소프트웨어를 도입해 디지털화를 이어간다. 앞서 도입한 Portchain Connect에 이은 것으로, 분산된 수작업 계획을 선석·크레인·갱(gang) 계획을 통합하는 중앙집중형 솔루션으로 대체하고 실시간 선박 추적과 시나리오 계획 기능을 지원한다. 선사·고객에게는 지속 갱신되는 선석 라인업 접근권을 제공해 이메일·전화 문의를 줄인다.", "eSum": "Lithuania's Klaipeda Container Terminal (KCT) has implemented Portchain's 'Quay' berth planning software, continuing its digitalisation after deploying Portchain Connect earlier in 2026. The platform replaces fragmented manual planning with a centralised solution for berth, crane and gang planning, supported by real-time vessel tracking and scenario planning. Shipping lines and customers gain access to a continuously updated berth lineup, reducing email and phone enquiries.", "kImp": "터미널 선석운영의 실시간·중앙집중형 계획 전환으로 항만 생산성과 고객 투명성이 높아진다.", "eImp": "Shifting terminal berth operations to real-time centralised planning boosts port productivity and customer transparency.", "url": "https://container-news.com/klaipeda-container-terminal-implements-portchain-quay/"}, {"code": "SYS", "title": "PTC·bigyellowfish, 선원 건강관리 플랫폼 접근 확대", "src": "Smart Maritime Network", "date": "2026-08-05", "kSum": "필리핀 선원 인력공급사 PTC(Philippine Transmarine Carriers)와 자회사 JPMI가 bigyellowfish와 협약해 필리핀 선원 대상 건강·웰니스 플랫폼 접근을 확대한다. 이 플랫폼은 선주·선박관리사에게 선원·선박별 건강 위험 데이터를 제공해 선내 사고와 의료 하선을 줄이고, 선원에게는 영양·운동·정신건강·예방관리 등 개인화 콘텐츠와 게이미피케이션 기능을 제공한다. 우선 선정된 선주 대상 파일럿으로 도입한 뒤 확대할 예정이다.", "eSum": "Philippine crewing provider PTC (Philippine Transmarine Carriers) and its subsidiary JPMI have signed with bigyellowfish to expand access to a health and wellness platform for Filipino seafarers. The platform gives shipowners and managers crew and vessel health-risk data to reduce onboard incidents and medical repatriations, while offering seafarers personalised content on nutrition, fitness, mental wellbeing and preventative care with gamification features. It will roll out via pilot projects with selected principals before wider deployment.", "kImp": "선원 복지 데이터를 선박관리 의사결정에 연결하는 디지털 플랫폼으로 의료 하선 등 운영 리스크 저감이 기대된다.", "eImp": "A digital platform linking seafarer welfare data to ship-management decisions could cut medical repatriations and operational risk.", "url": "https://smartmaritimenetwork.com/2026/08/05/ptc-and-bigyellowfish-expand-access-to-seafarer-health-platform/"}]}, {"code": "SMGR", "type": "news", "kTitle": "Section 21. 선박관리사", "eTitle": "Section 21. Ship Managers", "items": [{"code": "SMGR", "title": "Life at Sea: Nisha Mohanty's Journey with Synergy Marine Group", "src": "Synergy Marine Group", "date": "2026-08-07", "kSum": "시너지마린그룹(Synergy Marine Group)이 견습 기관사(Trainee Marine Engineer)로 승선 중인 니샤 모한티(Nisha Mohanty)의 인터뷰를 공개했다. 그녀는 승선 배치 두 차례를 마친 초급 여성 기관사로, 안전 문화, 팀워크, 선임 사관의 멘토링, 기술·디지털 역량 개발에 관한 경험을 나눴다. 시너지는 이 기사를 통해 사관후보생과 기관사 대상 경력 개발 경로와 포용적 해상 근무 환경을 부각했다.", "eSum": "Synergy Marine Group published an interview with Nisha Mohanty, a Trainee Marine Engineer who has completed two vessel assignments. She discusses the company's practical safety culture, teamwork, mentoring by senior officers, and growing technical and digital skills at sea. Synergy uses the piece to highlight its cadet and engineer career-development pathways and an increasingly inclusive shipboard workplace.", "kImp": "선원 복지와 여성 인재 육성을 강조하는 대형 선박관리사의 인재 개발 노력을 보여주는 긍정 사례다.", "eImp": "A positive example of a major ship manager's talent-development and seafarer-welfare efforts, spotlighting inclusion and female engineers at sea.", "url": "https://www.synergymarinegroup.com/life-at-synergy/life-at-sea-nisha-mohantys-journey-with-synergy-marine-group/"}, {"code": "SMGR", "title": "Snack smarter: Power up your day without the sugar crash (BSM Catering)", "src": "SAFETY4SEA (BSM Compass to Wellbeing)", "date": "2026-08-03", "kSum": "버나드슐테십매니지먼트(Bernhard Schulte Shipmanagement, BSM)의 케이터링 부문 수석 영양사 스텔라 레온티우(Stella Leontiou)가 선원 대상 건강 간식 가이드를 SAFETY4SEA의 'Compass to Wellbeing' 칼럼을 통해 소개했다. 간식 자체가 문제가 아니라 무엇을, 왜 먹느냐가 중요하다며 혈당 급락(sugar crash)을 피하는 현명한 간식 선택법을 제시했다. BSM의 선원 복지·건강 지원 활동의 일환이다.", "eSum": "Stella Leontiou, Head Nutritionist at BSM Catering (Bernhard Schulte Shipmanagement), shared seafarer-focused healthy snacking guidance via SAFETY4SEA's 'Compass to Wellbeing' column. She stressed that snacking is not the enemy - what and why we snack is what matters - and offered tips to avoid the sugar crash. It reflects BSM's ongoing crew wellbeing and health support.", "kImp": "주요 선박관리사 BSM이 선원 영양·웰빙 지원을 지속하며 건강한 승선 문화를 촉진하고 있음을 보여준다.", "eImp": "Shows major ship manager BSM continuing to support seafarer nutrition and wellbeing, promoting a healthier onboard culture.", "url": "https://safety4sea.com/snack-smarter-power-up-your-day-without-the-sugar-crash/"}, {"code": "SMGR", "title": "PTC pilots Bigyellowfish health platform across selected fleets", "src": "Splash247", "date": "2026-08-05", "kSum": "필리핀 트랜스마린 캐리어스(Philippine Transmarine Carriers, PTC)와 옌센 PTC 마리타임(Jebsen PTC Maritime)이 선정된 선주사 선대를 대상으로 빅옐로피시(Bigyellowfish)의 디지털 건강 플랫폼 시범 운영을 준비 중이다. 이 시스템은 선박 단위 건강 위험 프로파일을 제공해 사고나 의료 하선 이전에 문제를 조기 식별하며, 이미 12만 명 이상의 해기 종사자가 등록돼 있다. 선원들은 영양·피트니스·정신건강·예방 관리에 대한 맞춤형 자료와 게임화(gamification) 기능을 제공받는다.", "eSum": "Philippine Transmarine Carriers (PTC) and Jebsen PTC Maritime are preparing to pilot Bigyellowfish's digital health platform with selected shipping principals. The system gives owners and managers vessel-level health risk profiles to spot problems before incidents or medical repatriations, with more than 120,000 maritime professionals already enrolled. Seafarers receive personalised nutrition, fitness, mental wellbeing and preventive-care resources, with gamification to boost engagement.", "kImp": "선원관리 기업이 디지털 건강 데이터를 선대 관리에 접목해 선원 복지와 예방적 건강관리를 강화하는 사례다.", "eImp": "A crew manager embedding digital health data into fleet management to strengthen seafarer welfare and preventive care.", "url": "https://splash247.com/ptc-pilots-bigyellowfish-health-platform-across-selected-fleets/"}]}]};